{'content': '// Print-in-Place Planetary Gearbox
// Material: PETG, Nozzle: 0.4mm, Layer height: 0.1mm
// All gear axes vertical (Z-up)

// === PARAMETERS ===
$fn = 120;

// Gear parameters
module_val = 1.5;        // Module (mm)
pressure_angle = 20;     // Standard pressure angle
sun_teeth = 16;          // Sun gear teeth
planet_teeth = 8;        // Planet gear teeth
// Ring teeth = sun + 2*planet
ring_teeth = sun_teeth + 2 * planet_teeth; // = 32

num_planets = 3;

// Derived pitch radii
sun_r = module_val * sun_teeth / 2;      // 12mm
planet_r = module_val * planet_teeth / 2; // 6mm
ring_r = module_val * ring_teeth / 2;    // 24mm
orbit_r = sun_r + planet_r;              // 18mm (center distance)

// Gear dimensions
gear_height = 10;         // Height of gear teeth
gear_clearance = 0.30;    // Radial clearance between meshing gears (PETG needs ~0.3mm)
axial_clearance = 0.30;   // Vertical clearance between layers

// Ring gear
ring_outer_r = ring_r + module_val + 4;  // Outer radius of ring housing
ring_wall = ring_outer_r - (ring_r + module_val); // Wall thickness outside ring teeth

// Carrier parameters
carrier_shaft_r = 2.5;    // Planet axle radius
carrier_clearance = 0.30; // Clearance around carrier

// Heights
base_height = 2;          // Bottom carrier plate
top_height = 2;           // Top carrier plate
total_height = base_height + axial_clearance + gear_height + axial_clearance + top_height;

// Sun gear handle
sun_handle_r = 5;
sun_handle_h = 8;

// === INVOLUTE GEAR FUNCTIONS ===

function involute_point(base_r, angle) = 
    base_r * [cos(angle) + angle * PI/180 * sin(angle),
              sin(angle) - angle * PI/180 * cos(angle)];

function involute_intersect_angle(base_r, r) = 
    sqrt(pow(r/base_r, 2) - 1) * 180 / PI;

module involute_gear(num_teeth, mod, p_angle, height, clearance=0) {
    pitch_r = mod * num_teeth / 2;
    base_r = pitch_r * cos(p_angle);
    addendum = mod;
    dedendum = mod * 1.25;
    outer_r = pitch_r + addendum - clearance;
    root_r = pitch_r - dedendum + clearance;

    tooth_angle = 360 / num_teeth;

    // Approximate involute with polygon points
    steps = 15;

    linear_extrude(height=height) {
        // Build gear as a union of teeth on a base circle
        difference() {
            union() {
                circle(r=max(root_r, base_r));
                for (i = [0:num_teeth-1]) {
                    rotate([0, 0, i * tooth_angle])
                        involute_tooth_2d(base_r, root_r, outer_r, pitch_r, num_teeth, mod, p_angle, clearance);
                }
            }
        }
    }
}

module involute_tooth_2d(base_r, root_r, outer_r, pitch_r, num_teeth, mod, p_angle, clearance) {
    steps = 20;
    tooth_angle = 360 / num_teeth;

    // Angular half-thickness of tooth at pitch circle
    half_thick_angle = 90 / num_teeth - clearance / pitch_r * 180 / PI;

    // Generate involute curve points
    min_r = max(base_r, root_r);

    function inv_angle(r) = 
        (sqrt(pow(r/base_r, 2) - 1) * 180 / PI) - involute_intersect_angle(base_r, pitch_r);

    points_right = [for (i = [0:steps]) 
        let(r = min_r + (outer_r - min_r) * i / steps,
            a = inv_angle(r) + half_thick_angle)  // Removed negative
        [r * cos(a), r * sin(a)]
    ];

    points_left = [for (i = [0:steps])
        let(r = min_r + (outer_r - min_r) * i / steps,
            a = -(inv_angle(r) + half_thick_angle) + tooth_angle)  // Mirror with offset
        [r * cos(a), r * sin(a)]
    ];

    // This approach is getting complex. Let me use a simpler but effective gear profile.
    polygon(concat(
        [[root_r * cos(-half_thick_angle + tooth_angle), root_r * sin(-half_thick_angle + tooth_angle)]],
        [for (i = [steps:-1:0]) points_left[i]],
        [for (i = [0:steps]) points_right[i]],
        [[root_r * cos(half_thick_angle), root_r * sin(half_thick_angle)]]
    ));
}

// === SIMPLIFIED GEAR USING BUILT-IN APPROACH ===
// Use a well-tested parametric gear tooth profile

module simple_gear(teeth, mod, p_angle, height, backlash=0) {
    pitch_r = mod * teeth / 2;
    base_r = pitch_r * cos(p_angle);
    addendum = mod * 1.0;
    dedendum = mod * 1.25;
    outer_r = pitch_r + addendum;
    root_r = pitch_r - dedendum;
    tooth_angle = 360 / teeth;

    // Tooth half-angle at pitch circle (accounting for backlash)
    alpha = 90/teeth - (backlash/2) / pitch_r * 180/PI;

    linear_extrude(height=height)
    union() {
        circle(r=max(root_r + 0.01, 0.1));
        for (i = [0:teeth-1]) {
            rotate([0,0, i*tooth_angle])
            gear_tooth_2d(pitch_r, base_r, outer_r, root_r, alpha, teeth);
        }
    }
}

module gear_tooth_2d(pitch_r, base_r, outer_r, root_r, alpha, teeth) {
    n = 12;
    min_r = max(base_r, root_r);

    function inv(r) = sqrt(max(0, (r*r)/(base_r*base_r) - 1)) * 180/PI;
    pitch_inv = inv(pitch_r);

    pts_r = [for(i=[0:n]) let(r = min_r + (outer_r - min_r)*i/n,
                               a = alpha + pitch_inv - inv(r))
             [r*cos(a), r*sin(a)]];

    pts_l = [for(i=[0:n]) let(r = min_r + (outer_r - min_r)*i/n,
                               a = -(alpha + pitch_inv - inv(r)))
             [r*cos(a), r*sin(a)]];

    polygon(concat(
        [[root_r*cos(-alpha*0.5), root_r*sin(-alpha*0.5)]],
        pts_l,
        [[outer_r*cos(0), outer_r*sin(0)]],  // tip
        [for(i=[n:-1:0]) pts_r[i]],
        [[root_r*cos(alpha*0.5), root_r*sin(alpha*0.5)]]
    ));
}

// === INTERNAL (RING) GEAR ===
module ring_gear(teeth, mod, p_angle, height, outer_radius, backlash=0) {
    pitch_r = mod * teeth / 2;
    base_r = pitch_r * cos(p_angle);
    addendum = mod * 1.0;
    dedendum = mod * 1.25;
    // For internal gear, addendum goes inward, dedendum outward
    inner_r = pitch_r - addendum;  // Tooth tips go inward
    root_r = pitch_r + dedendum;   // Tooth roots go outward
    tooth_angle = 360 / teeth;

    alpha = 90/teeth - (backlash/2) / pitch_r * 180/PI;

    linear_extrude(height=height)
    difference() {
        circle(r=outer_radius);
        // Cut away the space between teeth, leaving teeth protruding inward
        circle(r=inner_r);
        // Now add teeth back by subtracting the inverse
        // Actually, for ring gear: start with annulus, subtract tooth spaces
    }

    // Better approach: ring gear as difference
    linear_extrude(height=height)
    difference() {
        circle(r=outer_radius);
        ring_gear_inner_2d(teeth, mod, p_angle, backlash);
    }
}

module ring_gear_inner_2d(teeth, mod, p_angle, backlash=0) {
    pitch_r = mod * teeth / 2;
    base_r = pitch_r * cos(p_angle);
    addendum = mod * 1.0;
    dedendum = mod * 1.25;
    inner_r = pitch_r - addendum;
    root_r = pitch_r + dedendum;
    tooth_angle = 360 / teeth;
    n = 12;

    alpha = 90/teeth + (backlash/2) / pitch_r * 180/PI;

    function inv(r) = sqrt(max(0, (r*r)/(base_r*base_r) - 1)) * 180/PI;
    pitch_inv = inv(pitch_r);

    // For internal gear, the involute profile is mirrored
    // Teeth point inward, so we create the bore profile

    // Generate the full internal profile as a polygon
    profile = [for(t=[0:teeth-1]) 
        for(p=ring_tooth_profile(pitch_r, base_r, inner_r, root_r, alpha, pitch_inv, n, t*tooth_angle))
        p
    ];
    polygon(profile);
}

function ring_tooth_profile(pitch_r, base_r, inner_r, root_r, alpha, pitch_inv, n, offset) = 
    let(min_r = max(base_r, inner_r))
    concat(
        // Right flank of space (going from root to tip)
        [for(i=[0:n]) let(r = root_r - (root_r - min_r)*i/n,
                          a = offset + alpha + pitch_inv - involute_angle(r, base_r))
         [r*cos(a), r*sin(a)]],
        // Tip arc
        [for(i=[0:3]) let(a = offset - alpha - pitch_inv + involute_angle(min_r, base_r) + 
                           (offset + 360/len([0:0]) - offset)*0/1) // skip for now
         [0,0]],  // placeholder
        // Left flank
        [for(i=[0:n]) let(r = min_r + (root_r - min_r)*i/n,
                          a = offset - (alpha + pitch_inv - involute_angle(r, base_r)))
         [r*cos(a), r*sin(a)]]
    );

function involute_angle(r, base_r) = 
    sqrt(max(0, (r*r)/(base_r*base_r) - 1)) * 180/PI;

// OK, the involute approach is getting complex. Let me use a proven simpler method.
// I'll use the rack-approximation / simplified tooth profile that prints well.

// === CLEAN RESTART WITH PROVEN GEAR MODULE ===

// Simplified but functional gear profile using tangential arcs
module gear_ext(teeth, mod, height, backlash=0) {
    pr = mod*teeth/2;           // pitch radius
    ar = pr + mod;              // addendum (outer) radius  
    dr = pr - 1.25*mod;        // dedendum (root) radius
    br = pr * cos(20);         // base radius

    effective_backlash = backlash/2;

    linear_extrude(height=height, convexity=10)
    gear_profile_2d(teeth, mod, effective_backlash);
}

module gear_profile_2d(teeth, mod, bl=0) {
    pr = mod*teeth/2;
    ar = pr + mod;
    dr = pr - 1.25*mod;
    br = pr * cos(20);
    ta = 360/teeth;

    // Use polygon approximation of involute
    n = 10;

    function inv_a(r) = sqrt(max(0, r*r/(br*br)-1))*180/PI;
    inv_pr = inv_a(pr);
    half = 90/teeth - bl/pr*180/PI;
    mr = max(br, dr);

    tooth_pts = [for(t=[0:teeth-1]) each
        concat(
            // Right involute flank
            [for(i=[0:n]) let(r=mr+(ar-mr)*i/n, 
                              a=t*ta + half + inv_pr - inv_a(r))
             [r*cos(a), r*sin(a)]],
            // Left involute flank (reversed)
            [for(i=[n:-1:0]) let(r=mr+(ar-mr)*i/n,
                                 a=t*ta - half - inv_pr + inv_a(r))
             [r*cos(a), r*sin(a)]]
        )
    ];

    polygon(tooth_pts);
}

// Internal ring gear
module gear_int(teeth, mod, outer_r, height, backlash=0) {
    pr = mod*teeth/2;
    br = pr * cos(20);
    ar = pr - mod;          // Internal addendum (tips point inward)
    dr = pr + 1.25*mod;     // Internal dedendum (roots go outward)

    effective_backlash = backlash/2;

    linear_extrude(height=height, convexity=10)
    difference() {
        circle(r=outer_r);
        ring_profile_2d(teeth, mod, effective_backlash);
    }
}

module ring_profile_2d(teeth, mod, bl=0) {
    pr = mod*teeth/2;
    br = pr * cos(20);
    ar = pr - mod;        // tips inward
    dr = pr + 1.25*mod;   // roots outward
    ta = 360/teeth;
    n = 10;

    function inv_a(r) = sqrt(max(0, r*r/(br*br)-1))*180/PI;
    inv_pr = inv_a(pr);
    half = 90/teeth + bl/pr*180/PI;
    mr = max(br, ar);

    // Profile is the inner bore shape
    profile = [for(t=[0:teeth-1]) each
        concat(
            // Right flank going from root inward to tip
            [for(i=[0:n]) let(r=dr-(dr-mr)*i/n,
                              a=t*ta + half + inv_pr - inv_a(r))
             [r*cos(a), r*sin(a)]],
            // Left flank going from tip outward to root
            [for(i=[n:-1:0]) let(r=dr-(dr-mr)*i/n,
                                 a=t*ta - half - inv_pr + inv_a(r))
             [r*cos(a), r*sin(a)]]
        )
    ];

    polygon(profile);
}

// === ASSEMBLY ===

backlash = 0.4;  // Total backlash for PETG print-in-place

// Z positions
z_base = 0;
z_gears = base_height + axial_clearance;
z_top = z_gears + gear_height + axial_clearance;

// Colors for visualization
// Ring gear (stationary housing)
color("SteelBlue", 0.5)
ring_gear_assembly();

// Sun gear
color("Gold")
sun_gear_assembly();

// Planet gears
color("Tomato")
planet_gears_assembly();

// Carrier
color("LimeGreen", 0.7)
carrier_assembly();

// --- RING GEAR ASSEMBLY (fixed housing) ---
module ring_gear_assembly() {
    // Ring gear body - full height solid with internal gear teeth in middle
    difference() {
        cylinder(r=ring_outer_r, h=total_height);

        // Internal gear teeth region
        translate([0, 0, z_gears - 0.01])
        ring_bore(ring_teeth, module_val, gear_height + 0.02, backlash);

        // Bottom cavity for carrier plate
        translate([0, 0, z_base])
        cylinder(r=ring_r - module_val - carrier_clearance, h=base_height + axial_clearance + 0.01);

        // Top cavity for carrier plate  
        translate([0, 0, z_top - 0.01])
        cylinder(r=ring_r - module_val - carrier_clearance, h=top_height + axial_clearance + 0.02);

        // Center hole for sun shaft (bottom)
        translate([0, 0, -0.1])
        cylinder(r=sun_r - module_val + 1, h=base_height + axial_clearance + 0.2);

        // Center hole top for sun handle
        translate([0, 0, z_top - 0.01])
        cylinder(r=sun_handle_r + carrier_clearance + 0.5, h=top_height + 0.1);

        // Planet axle holes in bottom (clearance)
        for (i = [0:num_planets-1]) {
            rotate([0, 0, i * 360/num_planets])
            translate([orbit_r, 0, -0.1])
            cylinder(r=carrier_shaft_r + carrier_clearance + 0.5, h=base_height + 0.2);
        }
    }
}

module ring_bore(teeth, mod, height, bl) {
    pr = mod*teeth/2;
    br = pr * cos(20);
    ar = pr - mod;
    dr = pr + 1.25*mod;
    ta = 360/teeth;
    n = 10;

    function inv_a(r) = sqrt(max(0, r*r/(br*br)-1))*180/PI;
    inv_pr = inv_a(pr);
    half = 90/teeth + (bl/2)/pr*180/PI;
    mr = max(br, ar);

    linear_extrude(height=height, convexity=10) {
        profile = [for(t=[0:teeth-1]) each
            concat(
                [for(i=[0:n]) let(r=dr-(dr-mr)*i/n,
                                  a=t*ta + half + inv_pr - inv_a(r))
                 [r*cos(a), r*sin(a)]],
                [for(i=[n:-1:0]) let(r=dr-(dr-mr)*i/n,
                                     a=t*ta - half - inv_pr + inv_a(r))
                 [r*cos(a), r*sin(a)]]
            )
        ];
        polygon(profile);
    }
}

// --- SUN GEAR ASSEMBLY ---
module sun_gear_assembly() {
    // Sun gear in the middle
    translate([0, 0, z_gears])
    gear_ext(sun_teeth, module_val, gear_height, backlash);

    // Sun shaft going down through bottom
    translate([0, 0, -0.01])
    cylinder(r=sun_r - module_val - 0.5, h=z_gears + 0.02);

    // Sun handle going up through top
    translate([0, 0, z_gears + gear_height])
    cylinder(r=sun_handle_r, h=axial_clearance + top_height + sun_handle_h);

    // Hex grip on top
    translate([0, 0, total_height])
    linear_extrude(height=sun_handle_h)
    circle(r=sun_handle_r, $fn=6);
}

// --- PLANET GEARS ---
module planet_gears_assembly() {
    for (i = [0:num_planets-1]) {
        rotate([0, 0, i * 360/num_planets])
        translate([orbit_r, 0, z_gears])
        // Rotate planet to mesh correctly with sun
        rotate([0, 0, -(sun_teeth/planet_teeth) * (i * 360/num_planets) + 180/planet_teeth])
        planet_gear();
    }
}

module planet_gear() {
    difference() {
        gear_ext(planet_teeth, module_val, gear_height, backlash);
        // Center bore for carrier axle
        translate([0, 0, -0.1])
        cylinder(r=carrier_shaft_r + carrier_clearance, h=gear_height + 0.2);
    }
}

// --- CARRIER ASSEMBLY ---
module carrier_assembly() {
    carrier_r = ring_r - module_val - carrier_clearance - 0.5;

    // Bottom plate
    translate([0, 0, z_base])
    difference() {
        cylinder(r=carrier_r, h=base_height);
        // Center hole for sun shaft
        translate([0, 0, -0.1])
        cylinder(r=sun_r - module_val - 0.5 + carrier_clearance, h=base_height + 0.2);
    }

    // Planet axles
    for (i = [0:num_planets-1]) {
        rotate([0, 0, i * 360/num_planets])
        translate([orbit_r, 0, z_base])
        cylinder(r=carrier_shaft_r, h=total_height - top_height);
    }

    // Top plate  
    translate([0, 0, z_top])
    difference() {
        cylinder(r=carrier_r, h=top_height);
        // Center hole for sun handle
        translate([0, 0, -0.1])
        cylinder(r=sun_handle_r + carrier_clearance, h=top_height + 0.2);
        // Output features - hex socket or similar
    }

    // Output handle on bottom (extending down)
    translate([0, 0, -8])
    difference() {
        cylinder(r=carrier_r * 0.6, h=8, $fn=6);
        translate([0, 0, -0.1])
        cylinder(r=sun_r - module_val - 0.5 + carrier_clearance, h=8.2);
    }
}
'}

{'content': '// ============================================================
// Print-in-Place Planetary Gearbox
// PETG | 0.4mm nozzle | 0.1mm layer height | Z-up axis
// ============================================================
$fn = 128;

// === GEAR PARAMETERS ===
m       = 1.5;           // Module
PA      = 20;            // Pressure angle (degrees)
Ns      = 16;            // Sun teeth
Np      = 8;             // Planet teeth
Nr      = Ns + 2*Np;     // Ring teeth = 32
Nplanets = 3;

// Pitch radii
Rps = m*Ns/2;            // Sun pitch radius   = 12
Rpp = m*Np/2;            // Planet pitch radius = 6
Rpr = m*Nr/2;            // Ring pitch radius   = 24
Rc  = Rps + Rpp;         // Orbit radius        = 18

// === PRINT-IN-PLACE CLEARANCES ===
backlash    = 0.40;      // Circumferential backlash (total)
radial_clr  = 0.30;      // Radial gap between non-meshing surfaces
axial_clr   = 0.30;      // Vertical gap between sliding surfaces

// === DIMENSIONS ===
gear_h      = 12;        // Gear tooth height
base_h      = 2.5;       // Bottom carrier plate
top_h       = 2.5;       // Top carrier plate
total_h     = base_h + axial_clr + gear_h + axial_clr + top_h;

ring_outer  = Rpr + 1.25*m + 3.5;  // Ring outer radius
axle_r      = 2.0;       // Planet axle radius
sun_bore    = 4.0;       // Sun shaft radius (for carrier bore)

// Z coordinates
z_base  = 0;
z_gear  = base_h + axial_clr;
z_top   = z_gear + gear_h + axial_clr;

// ============================================================
// INVOLUTE GEAR TOOTH 2D PROFILE
// ============================================================
module gear2d(teeth, mod, pa, bl=0) {
    pr = mod * teeth / 2;
    br = pr * cos(pa);
    ar = pr + mod;              // Addendum radius
    rr = pr - 1.25 * mod;      // Root radius (dedendum)
    ta = 360 / teeth;
    n  = 20;                    // Involute resolution

    function inv_ang(r) = 
        (r <= br) ? 0 : sqrt(r*r/(br*br) - 1) * 180 / PI;

    inv_at_pr = inv_ang(pr);
    // Half tooth thickness angle at pitch circle, minus backlash
    half_tooth = (90/teeth) - (bl/2)/pr * 180/PI;

    start_r = max(br, rr);

    // One tooth profile: right flank + tip + left flank + root
    module one_tooth() {
        // Right side involute points (CCW from root to tip)
        r_pts = [for(i=[0:n]) 
            let(r = start_r + (ar - start_r) * i / n,
                a = half_tooth + inv_at_pr - inv_ang(r))
            [r*cos(a), r*sin(a)]
        ];

        // Left side involute points (CW from tip to root)
        l_pts = [for(i=[n:-1:0])
            let(r = start_r + (ar - start_r) * i / n,
                a = -(half_tooth + inv_at_pr - inv_ang(r)))
            [r*cos(a), r*sin(a)]
        ];

        polygon(concat(r_pts, l_pts));
    }

    union() {
        circle(r=start_r);
        for(i=[0:teeth-1])
            rotate([0,0,i*ta])
                one_tooth();
    }
}

// ============================================================
// INTERNAL (RING) GEAR 2D PROFILE — bore shape
// ============================================================
module ring_bore_2d(teeth, mod, pa, bl=0) {
    pr = mod * teeth / 2;
    br = pr * cos(pa);
    // Internal gear: addendum inward, dedendum outward
    ar = pr - mod;              // Tip radius (inward)
    rr = pr + 1.25 * mod;      // Root radius (outward)
    ta = 360 / teeth;
    n  = 20;

    function inv_ang(r) = 
        (r <= br) ? 0 : sqrt(r*r/(br*br) - 1) * 180 / PI;

    inv_at_pr = inv_ang(pr);
    // For internal gear, increase space (add backlash to space, not tooth)
    half_space = (90/teeth) + (bl/2)/pr * 180/PI;

    start_r = max(br, ar);

    // Generate full profile as single polygon
    // Go around CCW, for each tooth: root arc, right flank down, tip, left flank up
    pts = [for(t=[0:teeth-1]) each
        concat(
            // Left flank: from root down to tip
            [for(i=[0:n])
                let(r = rr - (rr - start_r) * i / n,
                    a = t*ta + half_space + inv_at_pr - inv_ang(r))
                [r*cos(a), r*sin(a)]
            ],
            // Right flank: from tip up to root
            [for(i=[0:n])
                let(r = start_r + (rr - start_r) * i / n,
                    a = t*ta - (half_space + inv_at_pr - inv_ang(rr - (rr-start_r)*i/n)))
                [r*cos(a), r*sin(a)]
            ]
        )
    ];

    // Hmm, let me simplify the right flank
    pts2 = [for(t=[0:teeth-1]) each
        concat(
            // Left flank descending (root to tip)
            [for(i=[0:n])
                let(r = rr - (rr - start_r) * i / n,
                    a = t*ta + half_space + inv_at_pr - inv_ang(r))
                [r*cos(a), r*sin(a)]
            ],
            // Right flank ascending (tip to root)  
            [for(i=[0:n])
                let(r = start_r + (rr - start_r) * i / n,
                    a = t*ta - half_space - inv_at_pr + inv_ang(r))
                [r*cos(a), r*sin(a)]
            ]
        )
    ];

    polygon(pts2);
}

// ============================================================
// COMPONENT: RING GEAR (Housing - Fixed)
// ============================================================
module ring_assembly() {
    carrier_bore_r = Rpr - 1.25*m - radial_clr;

    difference() {
        // Outer cylinder
        cylinder(r=ring_outer, h=total_h);

        // Gear teeth bore (middle section)
        translate([0, 0, z_gear - 0.01])
        linear_extrude(height=gear_h + 0.02, convexity=10)
        ring_bore_2d(Nr, m, PA, backlash);

        // Bottom cavity for carrier plate
        translate([0, 0, -0.01])
        cylinder(r=carrier_bore_r, h=z_gear + 0.01);

        // Top cavity for carrier plate
        translate([0, 0, z_top])
        cylinder(r=carrier_bore_r, h=top_h + 0.01);

        // Sun shaft hole through bottom
        translate([0, 0, -0.1])
        cylinder(r=sun_bore + radial_clr, h=z_gear + 0.2);

        // Sun shaft hole through top
        translate([0, 0, z_top - 0.01])
        cylinder(r=sun_bore + radial_clr, h=top_h + 0.1);

        // Grip features on outside - flats for holding
        for(i=[0:5])
            rotate([0, 0, i*60 + 30])
            translate([ring_outer + 1, 0, -0.1])
            cylinder(r=3, h=total_h + 0.2, $fn=32);
    }
}

// ============================================================
// COMPONENT: SUN GEAR
// ============================================================
module sun_assembly() {
    // Gear teeth
    translate([0, 0, z_gear])
    linear_extrude(height=gear_h, convexity=10)
    gear2d(Ns, m, PA, backlash);

    // Shaft down through bottom (input)
    cylinder(r=sun_bore, h=z_gear + 0.01);

    // Shaft up through top
    translate([0, 0, z_gear + gear_h])
    cylinder(r=sun_bore, h=total_h - (z_gear + gear_h) + 0.01);

    // Input handle below (hex)
    translate([0, 0, -10])
    linear_extrude(height=10)
    circle(r=sun_bore + 3, $fn=6);

    // Output indicator on top
    translate([0, 0, total_h])
    linear_extrude(height=5)
    circle(r=sun_bore + 2, $fn=6);
}

// ============================================================
// COMPONENT: PLANET GEARS
// ============================================================
module planet_assembly() {
    for(i=[0:Nplanets-1]) {
        a = i * 360/Nplanets;
        rotate([0, 0, a])
        translate([Rc, 0, z_gear])
        // Phase each planet to mesh with sun
        rotate([0, 0, planet_phase(i)])
        difference() {
            linear_extrude(height=gear_h, convexity=10)
            gear2d(Np, m, PA, backlash);
            // Bore for carrier axle
            translate([0, 0, -0.1])
            cylinder(r=axle_r + radial_clr, h=gear_h + 0.2);
        }
    }
}

// Calculate planet rotation phase for proper meshing
function planet_phase(i) = 
    let(a = i * 360/Nplanets)
    -a * Ns/Np;

// ============================================================
// COMPONENT: CARRIER
// ============================================================
module carrier_assembly() {
    carrier_r = Rpr - 1.25*m - radial_clr - 0.5;

    // Bottom plate
    difference() {
        cylinder(r=carrier_r, h=base_h);
        // Sun bore
        translate([0, 0, -0.1])
        cylinder(r=sun_bore + radial_clr, h=base_h + 0.2);
    }

    // Planet axle pins (from bottom plate through gear zone to top plate)
    for(i=[0:Nplanets-1]) {
        rotate([0, 0, i * 360/Nplanets])
        translate([Rc, 0, 0])
        cylinder(r=axle_r, h=z_top + top_h);
    }

    // Top plate
    translate([0, 0, z_top])
    difference() {
        cylinder(r=carrier_r, h=top_h);
        // Sun bore
        translate([0, 0, -0.1])
        cylinder(r=sun_bore + radial_clr, h=top_h + 0.2);
    }

    // Output handle on top (extending above ring)
    translate([0, 0, total_h])
    difference() {
        cylinder(r=carrier_r * 0.7, h=8, $fn=6);
        translate([0, 0, -0.1])
        cylinder(r=sun_bore + radial_clr + 1, h=8.2);
    }
}

// ============================================================
// FULL ASSEMBLY
// ============================================================
color("SteelBlue", 0.6)   ring_assembly();
color("Gold")              sun_assembly();
color("Tomato")            planet_assembly();
color("LimeGreen", 0.7)   carrier_assembly();
'}

{'content': '// ============================================================
// Print-in-Place Planetary Gearbox
// PETG | 0.4mm nozzle | 0.1mm layer height | Z-up axis
// ============================================================
$fn = 128;

// === GEAR PARAMETERS ===
modul   = 1.5;           // Module
PA      = 20;            // Pressure angle (degrees)
Ns      = 16;            // Sun teeth
Np      = 8;             // Planet teeth
Nr      = Ns + 2*Np;     // Ring teeth = 32
Nplanets = 3;

// Pitch radii
Rps = modul*Ns/2;        // Sun pitch radius   = 12
Rpp = modul*Np/2;        // Planet pitch radius = 6
Rpr = modul*Nr/2;        // Ring pitch radius   = 24
Rc  = Rps + Rpp;         // Orbit radius        = 18

// === PRINT-IN-PLACE CLEARANCES ===
backlash    = 0.45;      // Total backlash for PETG
radial_clr  = 0.35;      // Radial gap
axial_clr   = 0.35;      // Vertical gap

// === DIMENSIONS ===
gear_h      = 12;        // Gear tooth height
base_h      = 2.5;       // Bottom carrier plate
top_h       = 2.5;       // Top carrier plate
total_h     = base_h + axial_clr + gear_h + axial_clr + top_h;

ring_outer  = Rpr + 1.25*modul + 4;
axle_r      = 2.2;       // Planet axle radius
sun_shaft_r = 4.5;       // Sun shaft radius

// Z coordinates
z_gear  = base_h + axial_clr;
z_top   = z_gear + gear_h + axial_clr;

// ============================================================
// INVOLUTE GEAR PROFILE (external)
// ============================================================
module ext_gear_2d(teeth, mod, pa, total_backlash=0) {
    pr = mod * teeth / 2;
    br = pr * cos(pa);
    or_ = pr + mod;
    rr = pr - 1.25 * mod;
    ta = 360 / teeth;
    n  = 20;
    bl = total_backlash / 2;  // Per-side backlash

    function inv(r) = (r <= br) ? 0 : sqrt(r*r/(br*br) - 1) * 180 / PI;

    pitch_inv = inv(pr);
    half_tooth = 90/teeth - bl/pr * 180/PI;
    sr = max(br, rr);  // Start radius

    // Generate complete profile
    profile = [for(t=[0:teeth-1]) each [
        // Root arc start point
        let(a1 = t*ta - half_tooth) [sr*cos(a1), sr*sin(a1)],
        // Right involute flank (root to tip)
        for(i=[1:n])
            let(r = sr + (or_ - sr) * i / n,
                a = t*ta + half_tooth + pitch_inv - inv(r))
            [r*cos(a), r*sin(a)],
        // Left involute flank (tip to root)
        for(i=[n:-1:1])
            let(r = sr + (or_ - sr) * i / n,
                a = t*ta - half_tooth - pitch_inv + inv(r))
            [r*cos(a), r*sin(a)]
    ]];

    polygon(profile);
}

// ============================================================  
// INTERNAL RING GEAR PROFILE (the hole shape)
// ============================================================
module int_gear_bore_2d(teeth, mod, pa, total_backlash=0) {
    pr = mod * teeth / 2;
    br = pr * cos(pa);
    // Internal: teeth point inward
    tip_r = pr - mod;           // Tips (inward)
    root_r = pr + 1.25 * mod;  // Roots (outward)
    ta = 360 / teeth;
    n  = 20;
    bl = total_backlash / 2;

    function inv(r) = (r <= br) ? 0 : sqrt(r*r/(br*br) - 1) * 180 / PI;

    pitch_inv = inv(pr);
    // For internal gear: tooth thickness at pitch = pi*m/2 + backlash
    // Space for external gear = pi*m/2 - backlash  
    // So internal tooth half angle is larger by backlash
    half_tooth = 90/teeth + bl/pr * 180/PI;
    sr = max(br, tip_r);

    // The bore profile traces the inner surface
    // Between teeth are spaces (going outward to root_r)
    // Teeth protrude inward to tip_r
    profile = [for(t=[0:teeth-1]) each [
        // Tooth tip region (inward)
        // Right flank: from space (root) down to tip
        for(i=[0:n])
            let(r = root_r - (root_r - sr) * i / n,
                a = t*ta + half_tooth + pitch_inv - inv(r))
            [r*cos(a), r*sin(a)],
        // Left flank: from tip up to space (root)
        for(i=[0:n])
            let(r = sr + (root_r - sr) * i / n,
                a = t*ta - half_tooth - pitch_inv + inv(r))
            [r*cos(a), r*sin(a)]
    ]];

    polygon(profile);
}

// ============================================================
// Calculate planet phase for correct meshing
// ============================================================
function planet_phase(idx) =
    let(angle_offset = idx * 360 / Nplanets)
    -angle_offset * Ns / Np + (180/Np);

// ============================================================
// RING GEAR (Housing)
// ============================================================
module ring_assembly() {
    carrier_bore = Rc + Rpp + modul * 0.3;  // Just clear of planet addendum
    carrier_plate_bore = Rpr - 1.5*modul;

    difference() {
        // Outer shell
        union() {
            cylinder(r=ring_outer, h=total_h);
            // Flange on bottom for grip
            cylinder(r=ring_outer + 2, h=2);
        }

        // Ring gear teeth bore (gear zone only)
        translate([0, 0, z_gear - 0.01])
        linear_extrude(height=gear_h + 0.02, convexity=10)
        int_gear_bore_2d(Nr, modul, PA, backlash);

        // Bottom cavity for carrier base plate
        translate([0, 0, -0.01])
        cylinder(r=carrier_plate_bore, h=z_gear + 0.01);

        // Top cavity for carrier top plate
        translate([0, 0, z_top])
        cylinder(r=carrier_plate_bore, h=top_h + 0.02);

        // Sun shaft through-hole bottom
        translate([0, 0, -0.1])
        cylinder(r=sun_shaft_r + radial_clr, h=total_h + 10);

        // Planet axle clearance holes in bottom plate region
        for(i=[0:Nplanets-1])
            rotate([0, 0, i * 360/Nplanets])
            translate([Rc, 0, -0.1])
            cylinder(r=axle_r + radial_clr + 0.3, h=z_gear + 0.1);

        // Planet axle clearance holes in top plate region  
        for(i=[0:Nplanets-1])
            rotate([0, 0, i * 360/Nplanets])
            translate([Rc, 0, z_top - 0.01])
            cylinder(r=axle_r + radial_clr + 0.3, h=top_h + 0.1);
    }
}

// ============================================================
// SUN GEAR
// ============================================================
module sun_assembly() {
    // Gear body
    translate([0, 0, z_gear])
    linear_extrude(height=gear_h, convexity=10)
    ext_gear_2d(Ns, modul, PA, backlash);

    // Shaft through entire height
    cylinder(r=sun_shaft_r, h=total_h);

    // Input handle below (hex knob)
    translate([0, 0, -12])
    difference() {
        linear_extrude(height=12)
        circle(r=8, $fn=6);
        // Arrow indicator
    }
}

// ============================================================
// PLANET GEARS
// ============================================================
module planet_assembly() {
    for(i=[0:Nplanets-1]) {
        a = i * 360/Nplanets;
        rotate([0, 0, a])
        translate([Rc, 0, z_gear])
        rotate([0, 0, planet_phase(i)])
        difference() {
            linear_extrude(height=gear_h, convexity=10)
            ext_gear_2d(Np, modul, PA, backlash);
            // Axle bore
            translate([0, 0, -0.1])
            cylinder(r=axle_r + radial_clr, h=gear_h + 0.2);
        }
    }
}

// ============================================================
// CARRIER (Output)
// ============================================================
module carrier_assembly() {
    carrier_r = Rpr - 1.5*modul - radial_clr;

    // Bottom plate
    translate([0, 0, 0])
    difference() {
        cylinder(r=carrier_r, h=base_h);
        translate([0, 0, -0.1])
        cylinder(r=sun_shaft_r + radial_clr, h=base_h + 0.2);
    }

    // Planet axle pins
    for(i=[0:Nplanets-1])
        rotate([0, 0, i * 360/Nplanets])
        translate([Rc, 0, 0])
        cylinder(r=axle_r, h=z_top + top_h);

    // Top plate
    translate([0, 0, z_top])
    difference() {
        cylinder(r=carrier_r, h=top_h);
        translate([0, 0, -0.1])
        cylinder(r=sun_shaft_r + radial_clr, h=top_h + 0.2);
    }

    // Output handle on top
    translate([0, 0, total_h])
    difference() {
        // Hex output shaft
        linear_extrude(height=10)
        circle(r=carrier_r * 0.6, $fn=6);
        // Sun hole through
        translate([0, 0, -0.1])
        cylinder(r=sun_shaft_r + radial_clr + 0.5, h=10.2);
    }
}

// ============================================================
// ASSEMBLY
// ============================================================
color("SteelBlue", 0.5)  ring_assembly();
color("Gold")             sun_assembly();
color("Tomato")           planet_assembly();
color("LimeGreen", 0.7)  carrier_assembly();
'}

{'content': '// ============================================================
// Print-in-Place Planetary Gearbox
// PETG | 0.4mm nozzle | 0.1mm layer height | Z-up axis
// Single stage, 3 planet gears
// ============================================================
$fn = 128;

// === GEAR PARAMETERS ===
modul   = 1.5;           // Module (mm)
PA      = 20;            // Pressure angle (degrees)
Ns      = 16;            // Sun teeth count
Np      = 8;             // Planet teeth count
Nr      = Ns + 2*Np;     // Ring teeth = 32 (must equal sun + 2*planet)
Nplan   = 3;             // Number of planets

// Pitch radii (mm)
Rps = modul*Ns/2;        // Sun pitch radius   = 12
Rpp = modul*Np/2;        // Planet pitch radius = 6
Rpr = modul*Nr/2;        // Ring pitch radius   = 24
Rorb = Rps + Rpp;        // Orbit radius        = 18

// Addendum/dedendum
addendum = modul;
dedendum = 1.25 * modul;

// === PRINT-IN-PLACE CLEARANCES (PETG, 0.4mm nozzle) ===
backlash    = 0.50;      // Total gear backlash
radial_clr  = 0.35;      // Radial clearance between sliding surfaces
axial_clr   = 0.40;      // Vertical clearance between layers

// === KEY DIMENSIONS ===
gear_h      = 12;        // Height of gear teeth
base_h      = 3.0;       // Bottom carrier disc thickness
top_h       = 3.0;       // Top carrier disc thickness
total_h     = base_h + axial_clr + gear_h + axial_clr + top_h;

ring_outer  = Rpr + dedendum + 4;  // Ring gear outer radius
axle_r      = 2.0;                 // Planet axle pin radius
sun_shaft_r = 4.0;                 // Sun gear shaft radius

// Z positions
Z0      = 0;                           // Bottom of part
Zgear   = base_h + axial_clr;          // Bottom of gear teeth
Ztop    = Zgear + gear_h + axial_clr;  // Bottom of top carrier plate
Ztotal  = Ztop + top_h;                // Top of part

// Carrier plate radius (must fit inside ring without touching teeth)
carrier_r = Rpr - dedendum - radial_clr;

echo("=== Planetary Gearbox Parameters ===");
echo("Sun pitch radius:", Rps);
echo("Planet pitch radius:", Rpp);
echo("Ring pitch radius:", Rpr);
echo("Orbit radius:", Rorb);
echo("Carrier plate radius:", carrier_r);
echo("Ring outer radius:", ring_outer);
echo("Total height:", Ztotal);
echo("Gear ratio (ring fixed):", 1 + Nr/Ns);

// ============================================================
// INVOLUTE FUNCTIONS
// ============================================================
function involute_angle(base_r, r) = 
    (r <= base_r) ? 0 : sqrt(r*r/(base_r*base_r) - 1) * 180 / PI;

// ============================================================
// EXTERNAL GEAR 2D PROFILE
// ============================================================
module ext_gear_2d(teeth, mod, pa, bl=0) {
    pr = mod * teeth / 2;
    br = pr * cos(pa);
    outer_r = pr + mod;
    root_r = max(pr - 1.25 * mod, 1);
    ta = 360 / teeth;
    n  = 24;

    pitch_inv = involute_angle(br, pr);
    half_thick = 90/teeth - (bl/2)/pr * 180/PI;
    sr = max(br, root_r);

    profile = [for(t=[0:teeth-1]) each [
        // Root point (right side)
        let(a = t*ta - half_thick - pitch_inv + involute_angle(br, sr))
            [sr*cos(a), sr*sin(a)],
        // Right involute (root to tip)
        for(i=[1:n])
            let(r = sr + (outer_r - sr) * i / n,
                a = t*ta + half_thick + pitch_inv - involute_angle(br, r))
            [r*cos(a), r*sin(a)],
        // Left involute (tip to root)
        for(i=[n-1:-1:0])
            let(r = sr + (outer_r - sr) * i / n,
                a = t*ta - half_thick - pitch_inv + involute_angle(br, r))
            [r*cos(a), r*sin(a)]
    ]];

    polygon(profile);
}

// ============================================================
// INTERNAL (RING) GEAR BORE 2D PROFILE
// ============================================================
module int_gear_bore_2d(teeth, mod, pa, bl=0) {
    pr = mod * teeth / 2;
    br = pr * cos(pa);
    tip_r = pr - mod;              // Tooth tips (inward)
    root_r = pr + 1.25 * mod;     // Between teeth (outward)
    ta = 360 / teeth;
    n  = 24;

    pitch_inv = involute_angle(br, pr);
    half_thick = 90/teeth + (bl/2)/pr * 180/PI;  // Wider for backlash
    sr = max(br, tip_r);

    // Trace the internal bore shape
    profile = [for(t=[0:teeth-1]) each [
        // Root (outer) region - right side going inward
        for(i=[0:n])
            let(r = root_r - (root_r - sr) * i / n,
                a = t*ta + half_thick + pitch_inv - involute_angle(br, r))
            [r*cos(a), r*sin(a)],
        // Left side going outward
        for(i=[1:n])
            let(r = sr + (root_r - sr) * i / n,
                a = t*ta - half_thick - pitch_inv + involute_angle(br, r))
            [r*cos(a), r*sin(a)]
    ]];

    polygon(profile);
}

// ============================================================
// Planet phase: ensure proper meshing with sun AND ring
// For Nr = Ns + 2*Np, and equal spacing, need Nr/Nplan to be integer
// Nr=32, Nplan=3 -> 32/3 is not integer!
// Let's check: for planets to be equally spaced, (Ns+Nr) must be
// divisible by Nplan.  Ns+Nr = 16+32 = 48, 48/3 = 16 ✓
// ============================================================
function planet_phase(idx) =
    let(orbit_angle = idx * 360 / Nplan)
    // Sun mesh: planet must rotate by -orbit_angle * Ns/Np
    // The half-pitch offset aligns internal/external meshing
    -orbit_angle * Ns/Np;

// ============================================================
// RING GEAR ASSEMBLY (Stationary housing)
// ============================================================
module ring_assembly() {
    difference() {
        union() {
            // Main cylinder body
            cylinder(r=ring_outer, h=Ztotal);
            // Bottom grip flange
            translate([0, 0, 0])
            cylinder(r=ring_outer + 2, h=3);
            // Top lip
            translate([0, 0, Ztotal - 1])
            cylinder(r=ring_outer + 1, h=1);
        }

        // === INTERNAL GEAR TEETH (gear zone) ===
        translate([0, 0, Zgear - 0.01])
        linear_extrude(height=gear_h + 0.02, convexity=10)
        int_gear_bore_2d(Nr, modul, PA, backlash);

        // === BOTTOM CAVITY (for carrier base plate) ===
        // This needs to be wide enough for the carrier plate
        // but the ring must bridge over it to form the gear zone floor
        translate([0, 0, -0.01])
        cylinder(r=carrier_r + radial_clr, h=base_h + axial_clr + 0.01);

        // === TOP CAVITY (for carrier top plate) ===
        translate([0, 0, Ztop])
        cylinder(r=carrier_r + radial_clr, h=top_h + 0.02);

        // === SUN SHAFT THROUGH-HOLE ===
        // Bottom (input side)
        translate([0, 0, -0.1])
        cylinder(r=sun_shaft_r + radial_clr, h=Ztotal + 20);

        // === CARRIER AXLE SLOTS ===
        // The carrier axle pins pass through the ring's top/bottom regions
        // Create arc slots so carrier can rotate
        // Bottom slots
        for(a=[0:360/($fn):359])
            for(i=[0:Nplan-1]) {
                // Actually, we need the axle holes to be open arcs
                // Since carrier rotates, we need full circular slots
            }

        // Simpler: make annular channels for the axle pins
        // Bottom channel (annular groove at orbit radius)
        translate([0, 0, -0.01])
        difference() {
            cylinder(r=Rorb + axle_r + radial_clr, h=base_h + axial_clr + 0.01);
            cylinder(r=Rorb - axle_r - radial_clr, h=base_h + axial_clr + 0.02);
        }

        // Top channel
        translate([0, 0, Ztop])
        difference() {
            cylinder(r=Rorb + axle_r + radial_clr, h=top_h + 0.02);
            cylinder(r=Rorb - axle_r - radial_clr, h=top_h + 0.03);
        }

        // Carrier output shaft hole through top
        translate([0, 0, Ztop - 0.01])
        cylinder(r=carrier_r * 0.55 + radial_clr, h=top_h + 20);
    }
}

// ============================================================
// SUN GEAR ASSEMBLY (Input)
// ============================================================
module sun_assembly() {
    // Gear teeth in gear zone
    translate([0, 0, Zgear])
    linear_extrude(height=gear_h, convexity=10)
    ext_gear_2d(Ns, modul, PA, backlash);

    // Continuous shaft from bottom handle to top
    cylinder(r=sun_shaft_r, h=Ztotal);

    // Input hex knob below
    translate([0, 0, -15]) {
        // Hex shaft
        linear_extrude(height=15)
        circle(r=sun_shaft_r + 4, $fn=6);

        // Pointer triangle on top for visual
    }
}

// ============================================================
// PLANET GEARS
// ============================================================
module planet_assembly() {
    for(i=[0:Nplan-1]) {
        orbit_a = i * 360/Nplan;
        rotate([0, 0, orbit_a])
        translate([Rorb, 0, Zgear])
        rotate([0, 0, planet_phase(i)])
        planet_gear();
    }
}

module planet_gear() {
    difference() {
        linear_extrude(height=gear_h, convexity=10)
        ext_gear_2d(Np, modul, PA, backlash);

        // Axle bore
        translate([0, 0, -0.1])
        cylinder(r=axle_r + radial_clr, h=gear_h + 0.2);
    }
}

// ============================================================
// CARRIER ASSEMBLY (Output)
// ============================================================
module carrier_assembly() {
    // Bottom plate
    difference() {
        cylinder(r=carrier_r, h=base_h);
        // Sun bore
        translate([0, 0, -0.1])
        cylinder(r=sun_shaft_r + radial_clr, h=base_h + 0.2);
    }

    // Planet axle pins (full height connecting plates through gear zone)
    for(i=[0:Nplan-1])
        rotate([0, 0, i * 360/Nplan])
        translate([Rorb, 0, 0])
        cylinder(r=axle_r, h=Ztop + top_h);

    // Top plate
    translate([0, 0, Ztop])
    difference() {
        cylinder(r=carrier_r, h=top_h);
        // Sun bore
        translate([0, 0, -0.1])
        cylinder(r=sun_shaft_r + radial_clr, h=top_h + 0.2);
    }

    // Output hex shaft on top
    translate([0, 0, Ztotal])
    difference() {
        linear_extrude(height=12)
        circle(r=carrier_r * 0.5, $fn=6);
        // Sun through-hole
        translate([0, 0, -0.1])
        cylinder(r=sun_shaft_r + radial_clr + 0.5, h=12.2);
    }
}

// ============================================================
// ASSEMBLY
// ============================================================
color("SteelBlue", 0.5) ring_assembly();
color("Gold")            sun_assembly();
color("Tomato")          planet_assembly();
color("LimeGreen", 0.6) carrier_assembly();
'}

{'content': '// ============================================================
// Print-in-Place Planetary Gearbox
// PETG | 0.4mm nozzle | 0.1mm layer height | Z-up axis
// Single stage, 3 planet gears
// ============================================================
$fn = 128;

// === GEAR PARAMETERS ===
modul   = 1.5;
PA      = 20;
Ns      = 16;            // Sun teeth
Np      = 8;             // Planet teeth
Nr      = Ns + 2*Np;     // Ring teeth = 32
Nplan   = 3;

// Pitch radii
Rps  = modul*Ns/2;       // 12
Rpp  = modul*Np/2;       // 6
Rpr  = modul*Nr/2;       // 24
Rorb = Rps + Rpp;        // 18

// Key radii
sun_outer   = Rps + modul;         // 13.5 sun addendum
planet_outer= Rpp + modul;         // 7.5 planet addendum
ring_root   = Rpr + 1.25*modul;    // 25.875 ring dedendum (outer)
ring_tip    = Rpr - modul;         // 23 ring addendum (inner tip)

// === CLEARANCES ===
backlash    = 0.50;
radial_clr  = 0.35;
axial_clr   = 0.40;

// === DIMENSIONS ===
gear_h      = 14;
base_h      = 3.0;
top_h       = 3.0;
Zgear       = base_h + axial_clr;
Ztop        = Zgear + gear_h + axial_clr;
Ztotal      = Ztop + top_h;

ring_outer  = ring_root + 3.5;     // ~29.4
axle_r      = 2.0;
sun_shaft_r = 4.0;

// Carrier plate: must clear ring gear tips
// Ring inner tip at Rpr - modul = 23
// Planet outer at orbit + planet_outer = 18 + 7.5 = 25.5
// Carrier plate must be smaller than ring_tip
carrier_r   = ring_tip - radial_clr;  // ~22.65

echo("Ring tip (inner):", ring_tip);
echo("Carrier plate radius:", carrier_r);
echo("Planet max extent:", Rorb + planet_outer);
echo("Total height:", Ztotal);
echo("Gear ratio (ring fixed):", 1 + Nr/Ns);

// ============================================================
// INVOLUTE
// ============================================================
function inv_angle(br, r) = (r <= br) ? 0 : sqrt(r*r/(br*br) - 1) * 180/PI;

// ============================================================
// EXTERNAL GEAR 2D
// ============================================================
module ext_gear_2d(teeth, mod, pa, bl=0) {
    pr = mod*teeth/2;
    br = pr*cos(pa);
    ar = pr + mod;
    rr = max(pr - 1.25*mod, 0.5);
    ta = 360/teeth;
    n  = 20;

    pi_inv = inv_angle(br, pr);
    ht = 90/teeth - (bl/2)/pr * 180/PI;
    sr = max(br, rr);

    profile = [for(t=[0:teeth-1]) each [
        let(a0 = t*ta - ht - pi_inv + inv_angle(br, sr))
            [sr*cos(a0), sr*sin(a0)],
        for(i=[1:n])
            let(r = sr + (ar-sr)*i/n,
                a = t*ta + ht + pi_inv - inv_angle(br, r))
            [r*cos(a), r*sin(a)],
        for(i=[n-1:-1:1])
            let(r = sr + (ar-sr)*i/n,
                a = t*ta - ht - pi_inv + inv_angle(br, r))
            [r*cos(a), r*sin(a)]
    ]];
    polygon(profile);
}

// ============================================================
// INTERNAL GEAR BORE 2D
// ============================================================
module int_bore_2d(teeth, mod, pa, bl=0) {
    pr = mod*teeth/2;
    br = pr*cos(pa);
    tip_r  = pr - mod;
    root_r = pr + 1.25*mod;
    ta = 360/teeth;
    n  = 20;

    pi_inv = inv_angle(br, pr);
    ht = 90/teeth + (bl/2)/pr * 180/PI;
    sr = max(br, tip_r);

    profile = [for(t=[0:teeth-1]) each [
        for(i=[0:n])
            let(r = root_r - (root_r-sr)*i/n,
                a = t*ta + ht + pi_inv - inv_angle(br, r))
            [r*cos(a), r*sin(a)],
        for(i=[1:n])
            let(r = sr + (root_r-sr)*i/n,
                a = t*ta - ht - pi_inv + inv_angle(br, r))
            [r*cos(a), r*sin(a)]
    ]];
    polygon(profile);
}

// ============================================================
// Planet phase
// ============================================================
function planet_phase(idx) =
    let(oa = idx * 360/Nplan)
    -oa * Ns/Np;

// ============================================================
// RING GEAR (Housing / Frame - stationary)
// ============================================================
module ring_assembly() {
    difference() {
        union() {
            // Main body
            cylinder(r=ring_outer, h=Ztotal);
            // Bottom flange for grip
            cylinder(r=ring_outer + 3, h=2.5);
            // Top flange
            translate([0,0,Ztotal-1.5])
            cylinder(r=ring_outer + 2, h=1.5);
        }

        // --- Ring gear teeth (gear zone) ---
        translate([0,0,Zgear-0.01])
        linear_extrude(height=gear_h+0.02, convexity=10)
        int_bore_2d(Nr, modul, PA, backlash);

        // --- Carrier cavities ---
        // Bottom: carrier plate sits here, needs to rotate freely
        // Cavity is a disc space for the carrier plate
        translate([0,0,-0.01])
        cylinder(r=carrier_r + radial_clr, h=base_h + axial_clr + 0.01);

        // Top: same for top plate
        translate([0,0,Ztop])
        cylinder(r=carrier_r + radial_clr, h=top_h + 0.02);

        // --- Carrier axle annular channels ---
        // Bottom region: axle pins go from base plate through to top
        // Need arc or annular groove so carrier can rotate
        translate([0,0,-0.01])
        difference() {
            cylinder(r=Rorb + axle_r + radial_clr, h=Zgear + 0.01);
            cylinder(r=Rorb - axle_r - radial_clr, h=Zgear + 0.02);
        }
        // Top region
        translate([0,0,Zgear + gear_h])
        difference() {
            cylinder(r=Rorb + axle_r + radial_clr, h=axial_clr + top_h + 0.02);
            cylinder(r=Rorb - axle_r - radial_clr, h=axial_clr + top_h + 0.03);
        }

        // --- Sun shaft through-hole (full height + handles) ---
        translate([0,0,-10])
        cylinder(r=sun_shaft_r + radial_clr, h=Ztotal + 30);

        // --- Carrier output shaft hole (top) ---
        translate([0,0,Ztop-0.01])
        cylinder(r=10 + radial_clr, h=top_h + 20);
        // But we need a lip to retain the carrier!
        // The top plate of the carrier is retained by the ring's top wall
        // The carrier output shaft passes through a hole in the ring top

        // Let me reconsider: the ring top wall should have a hole
        // just big enough for the carrier output shaft, not the full plate
    }
}

// ============================================================
// SUN GEAR (Input)
// ============================================================
module sun_assembly() {
    // Gear teeth
    translate([0,0,Zgear])
    linear_extrude(height=gear_h, convexity=10)
    ext_gear_2d(Ns, modul, PA, backlash);

    // Continuous shaft
    cylinder(r=sun_shaft_r, h=Ztotal);

    // Input hex below
    translate([0,0,-15])
    linear_extrude(height=15)
    circle(r=sun_shaft_r + 4, $fn=6);
}

// ============================================================
// PLANET GEARS
// ============================================================
module planet_assembly() {
    for(i=[0:Nplan-1]) {
        oa = i*360/Nplan;
        rotate([0,0,oa])
        translate([Rorb, 0, Zgear])
        rotate([0,0, planet_phase(i)])
        difference() {
            linear_extrude(height=gear_h, convexity=10)
            ext_gear_2d(Np, modul, PA, backlash);
            translate([0,0,-0.1])
            cylinder(r=axle_r + radial_clr, h=gear_h+0.2);
        }
    }
}

// ============================================================
// CARRIER (Output)
// ============================================================
module carrier_assembly() {
    output_shaft_r = 9;

    // Bottom plate
    difference() {
        cylinder(r=carrier_r, h=base_h);
        translate([0,0,-0.1])
        cylinder(r=sun_shaft_r + radial_clr, h=base_h+0.2);
    }

    // Planet axle pins
    for(i=[0:Nplan-1])
        rotate([0,0,i*360/Nplan])
        translate([Rorb, 0, 0])
        cylinder(r=axle_r, h=Ztop + top_h);

    // Top plate
    translate([0,0,Ztop])
    difference() {
        cylinder(r=carrier_r, h=top_h);
        translate([0,0,-0.1])
        cylinder(r=sun_shaft_r + radial_clr, h=top_h+0.2);
    }

    // Output hex shaft
    translate([0,0,Ztotal])
    difference() {
        linear_extrude(height=12)
        circle(r=output_shaft_r, $fn=6);
        translate([0,0,-0.1])
        cylinder(r=sun_shaft_r + radial_clr + 0.5, h=12.2);
    }
}

// ============================================================
// CROSS-SECTION VIEW (for debugging - comment out for final)
// ============================================================
//difference() {
//    union() {
        color("SteelBlue",0.5) ring_assembly();
        color("Gold")          sun_assembly();
        color("Tomato")        planet_assembly();
        color("LimeGreen",0.6) carrier_assembly();
//    }
//    translate([0,-50,-20]) cube([100,100,100]);
//}
'}

