{'content': '// ============================================================
// Print-in-Place Planetary Gearbox v3
// PETG | 0.4mm nozzle | 0.1mm layer height | Z-up axis
// Single stage, 3 planet gears
// 
// DESIGN STRATEGY:
// - Ring is one solid piece with internal teeth
// - Sun, planets, carrier are captured inside
// - Annular grooves allow carrier rotation
// - All overhangs ≤45° (self-supporting)
// - Adequate clearances prevent fusion
// ============================================================
$fn = 128;

// === GEAR PARAMETERS ===
modul = 1.5;
PA    = 20;
Ns    = 16;          // Sun teeth
Np    = 8;           // Planet teeth
Nr    = Ns + 2*Np;   // Ring = 32 teeth
Nplan = 3;

// Pitch radii
Rps  = modul*Ns/2;   // 12mm
Rpp  = modul*Np/2;   // 6mm
Rpr  = modul*Nr/2;   // 24mm
Rorb = Rps + Rpp;    // 18mm orbit

// Tooth extremes
sun_add  = Rps + modul;           // 13.5
sun_ded  = Rps - 1.25*modul;      // 10.125
plan_add = Rpp + modul;           // 7.5
plan_ded = Rpp - 1.25*modul;      // 4.125
ring_tip = Rpr - modul;           // 23 (inner tip)
ring_root= Rpr + 1.25*modul;     // 25.875 (inner root)

// === CLEARANCES ===
bl   = 0.50;    // Backlash
rclr = 0.35;    // Radial clearance
aclr = 0.40;    // Axial clearance

// === DIMENSIONS ===
gear_h = 14;
base_h = 3.0;    // Carrier bottom plate
top_h  = 3.0;    // Carrier top plate

// Z layers from bottom to top
Z0     = 0;
Zg     = base_h + aclr;           // Gear zone bottom
Zgt    = Zg + gear_h;             // Gear zone top
Zt     = Zgt + aclr;              // Top plate bottom
ZZ     = Zt + top_h;              // Total height

ring_OR = ring_root + 3.5;        // Outer radius of ring housing
axle_r  = 2.0;                    // Planet axle pin radius
sun_sr  = sun_ded - 0.5;          // Sun shaft radius (less than dedendum)
carrier_r = ring_tip - rclr - 0.5; // Carrier plate radius

// Output/input shaft
out_shaft_r = 8;
in_shaft_r  = sun_sr + 3;

echo("=== KEY DIMENSIONS ===");
echo("Ring outer:", ring_OR);
echo("Ring inner tip:", ring_tip);
echo("Carrier plate r:", carrier_r);
echo("Orbit radius:", Rorb);
echo("Sun shaft:", sun_sr);
echo("Axle pin:", axle_r);
echo("Total height:", ZZ);
echo("Gear ratio:", 1 + Nr/Ns);

// ============================================================
// INVOLUTE GEAR PROFILES
// ============================================================
function inv_a(br, r) = (r <= br) ? 0 : sqrt(r*r/(br*br)-1)*180/PI;

module ext_gear_2d(teeth, mod, pa, backlash=0) {
    pr=mod*teeth/2; br=pr*cos(pa); ar=pr+mod; rr=max(pr-1.25*mod,0.5);
    ta=360/teeth; n=20;
    pi=inv_a(br,pr); ht=90/teeth-(backlash/2)/pr*180/PI; sr=max(br,rr);
    polygon([for(t=[0:teeth-1]) each [
        let(a=t*ta-ht-pi+inv_a(br,sr)) [sr*cos(a),sr*sin(a)],
        for(i=[1:n]) let(r=sr+(ar-sr)*i/n, a=t*ta+ht+pi-inv_a(br,r)) [r*cos(a),r*sin(a)],
        for(i=[n-1:-1:1]) let(r=sr+(ar-sr)*i/n, a=t*ta-ht-pi+inv_a(br,r)) [r*cos(a),r*sin(a)]
    ]]);
}

module int_bore_2d(teeth, mod, pa, backlash=0) {
    pr=mod*teeth/2; br=pr*cos(pa); tr=pr-mod; rr=pr+1.25*mod;
    ta=360/teeth; n=20;
    pi=inv_a(br,pr); ht=90/teeth+(backlash/2)/pr*180/PI; sr=max(br,tr);
    polygon([for(t=[0:teeth-1]) each [
        for(i=[0:n]) let(r=rr-(rr-sr)*i/n, a=t*ta+ht+pi-inv_a(br,r)) [r*cos(a),r*sin(a)],
        for(i=[1:n]) let(r=sr+(rr-sr)*i/n, a=t*ta-ht-pi+inv_a(br,r)) [r*cos(a),r*sin(a)]
    ]]);
}

function planet_phase(idx) = -idx*360/Nplan*Ns/Np;

// ============================================================
// RING GEAR HOUSING
// The ring is built as a solid cylinder with cavities carved out.
// Key constraint: the bridge between bottom cavity and gear zone
// must be printable (flat horizontal bridge is OK at the gear zone floor).
// Similarly, bridge between gear zone and top cavity.
// 
// The ring needs annular channels at the orbit radius so the
// carrier axle pins can pass through the floor/ceiling of gear zone.
// These channels are in the horizontal bridge layers.
// ============================================================
module ring_housing() {
    difference() {
        // === SOLID OUTER BODY ===
        union() {
            cylinder(r=ring_OR, h=ZZ);
            // Bottom grip flange
            translate([0,0,0])
            difference() {
                cylinder(r=ring_OR+3, h=3);
                // Finger grip notches
                for(i=[0:5]) rotate([0,0,i*60])
                    translate([ring_OR+3,0,-0.1])
                    cylinder(r=3.5, h=3.2, $fn=24);
            }
        }

        // === GEAR TEETH CAVITY (gear zone) ===
        translate([0,0,Zg])
        linear_extrude(height=gear_h, convexity=10)
        int_bore_2d(Nr, modul, PA, bl);

        // === BOTTOM CARRIER CAVITY ===
        // Disc-shaped space for carrier bottom plate
        // Inner annulus from sun shaft hole to carrier edge
        translate([0,0,-0.01])
        cylinder(r=carrier_r + rclr, h=base_h + aclr + 0.01);

        // === TOP CARRIER CAVITY ===
        translate([0,0,Zt])
        cylinder(r=carrier_r + rclr, h=top_h + 0.02);

        // === AXLE PIN ANNULAR CHANNELS ===
        // These run through the "bridge" layers between cavities and gear zone
        // They're part of the bottom and top cavities already since
        // carrier_r > Rorb + axle_r, so axles are inside the cavity.
        // 
        // CHECK: carrier_r = 22.15, Rorb + axle_r = 20
        // YES, the axle pins at radius 18, diameter 4, fully inside carrier_r
        // So the bottom/top cavities already accommodate them!

        // === SUN SHAFT THROUGH-HOLE ===
        translate([0,0,-5])
        cylinder(r=sun_sr + rclr, h=ZZ+20);

        // === CARRIER OUTPUT SHAFT HOLE (top) ===
        // The carrier output shaft extends up from the top plate
        // Need hole through ring top wall = doesn't exist since top cavity
        // goes to ZZ. So we need the ring to extend above.
        // ACTUALLY: the top cavity goes from Zt to ZZ, and ring body also
        // ends at ZZ. So the carrier top plate is flush with ring top.
        // We need the ring to NOT extend above the carrier output shaft.
        // Solution: Make ring slightly taller and add a retaining lip.
    }
}

// Wait - I have a problem. If the top cavity extends to ZZ (the top of the ring),
// then the carrier top plate can just fall out the top. Similarly bottom.
// I need retaining features.
//
// REVISED APPROACH:
// - The ring has thin lips/shoulders that overhang the carrier plates
// - These lips prevent the carrier from sliding out axially
// - The lips must be printable (no downward-facing overhang issue since
//   they print on top of the carrier plate with clearance gap)
//
// Actually, for print-in-place, the standard approach is:
// 1. Bottom carrier plate sits in a pocket at the bottom of the ring
// 2. The ring gear zone walls act as retention (ring_tip < carrier_r)
//    Wait - ring_tip = 23 and carrier_r = 22.15, so carrier_r < ring_tip
//    This means the carrier plate CAN slide into the gear zone!
//    
// Let me fix this: make carrier_r LARGER than ring_tip so the carrier
// plates are trapped by the ring gear teeth walls.
// But carrier_r can't be larger than ring_tip or it would interfere.
//
// BETTER APPROACH: 
// The ring housing has a stepped bore:
// - Bottom: bore = carrier_r + clr (wide enough for carrier plate)
// - Gear zone: bore = ring teeth (narrower at tips = ring_tip = 23)
// - Top: bore = carrier_r + clr
// As long as carrier_r > ring_tip, the carrier plates are trapped!
// 
// carrier_r needs to be > ring_tip = 23
// But carrier plates also need to not interfere with ring teeth.
// The carrier plates are NOT in the gear zone height - they're above/below.
// So carrier_r can be larger than ring_tip!
// 
// Let's set carrier_r = ring_tip + 2 = 25 (between tip and root)
// The carrier plates sit in pockets where the ring bore is 25 + clr
// The gear zone has teeth going inward to 23
// So the carrier is axially trapped by the tooth tips!

// REVISED carrier radius
carrier_r2 = ring_tip + 1.5;  // 24.5mm, between ring tip (23) and ring root (25.875)

echo("REVISED carrier_r:", carrier_r2);
echo("Ring tip (traps carrier):", ring_tip);

// ============================================================
// REVISED RING HOUSING
// ============================================================
module ring_v2() {
    ring_top = ZZ + 2;  // Extend ring slightly above for top retention

    difference() {
        union() {
            cylinder(r=ring_OR, h=ring_top);
            // Grip flange
            difference() {
                cylinder(r=ring_OR+3, h=3);
                for(i=[0:5]) rotate([0,0,i*60])
                    translate([ring_OR+3,0,-0.1])
                    cylinder(r=3.5, h=3.2, $fn=24);
            }
        }

        // GEAR TEETH
        translate([0,0,Zg])
        linear_extrude(height=gear_h, convexity=10)
        int_bore_2d(Nr, modul, PA, bl);

        // BOTTOM CARRIER POCKET
        // Wide enough for carrier plate, but ring_tip is narrower -> traps plate
        translate([0,0,-0.01])
        cylinder(r=carrier_r2 + rclr, h=base_h + aclr + 0.01);

        // TOP CARRIER POCKET
        translate([0,0,Zt])
        cylinder(r=carrier_r2 + rclr, h=top_h + aclr);

        // AXLE PIN CHANNELS
        // Axle pins are at Rorb=18, radius axle_r=2 -> extend from r=16 to r=20
        // carrier_r2=24.5, so axles are fully inside carrier pocket already ✓

        // SUN SHAFT HOLE - full through
        translate([0,0,-5])
        cylinder(r=sun_sr + rclr, h=ring_top + 10);

        // CARRIER OUTPUT HOLE through ring top
        translate([0,0,Zt + top_h])
        cylinder(r=out_shaft_r + rclr, h=10);

        // SUN INPUT HOLE through ring bottom
        // Already covered by sun shaft hole
    }
}

// ============================================================
// SUN GEAR v2
// ============================================================
module sun_v2() {
    // Gear
    translate([0,0,Zg])
    linear_extrude(height=gear_h, convexity=10)
    ext_gear_2d(Ns, modul, PA, bl);

    // Shaft (full height of ring)
    cylinder(r=sun_sr, h=ZZ + 2);

    // Input hex knob below ring
    translate([0,0,-12])
    linear_extrude(height=12)
    circle(r=in_shaft_r, $fn=6);

    // Small indicator on top
    translate([0,0,ZZ+2])
    cylinder(r=sun_sr, h=3);
}

// ============================================================
// PLANETS v2
// ============================================================
module planets_v2() {
    for(i=[0:Nplan-1]) {
        rotate([0,0,i*360/Nplan])
        translate([Rorb,0,Zg])
        rotate([0,0,planet_phase(i)])
        difference() {
            linear_extrude(height=gear_h, convexity=10)
            ext_gear_2d(Np, modul, PA, bl);
            translate([0,0,-0.1])
            cylinder(r=axle_r+rclr, h=gear_h+0.2);
        }
    }
}

// ============================================================
// CARRIER v2
// ============================================================
module carrier_v2() {
    // Bottom plate (trapped by ring gear tips)
    difference() {
        cylinder(r=carrier_r2, h=base_h);
        translate([0,0,-0.1])
        cylinder(r=sun_sr+rclr, h=base_h+0.2);
    }

    // Axle pins
    for(i=[0:Nplan-1])
        rotate([0,0,i*360/Nplan])
        translate([Rorb,0,0])
        cylinder(r=axle_r, h=Zt+top_h);

    // Top plate
    translate([0,0,Zt])
    difference() {
        cylinder(r=carrier_r2, h=top_h);
        translate([0,0,-0.1])
        cylinder(r=sun_sr+rclr, h=top_h+0.2);
    }

    // Output hex shaft
    translate([0,0,Zt+top_h])
    difference() {
        linear_extrude(height=12)
        circle(r=out_shaft_r, $fn=6);
        translate([0,0,-0.1])
        cylinder(r=sun_sr+rclr+0.5, h=12.2);
    }
}

// ============================================================
// ASSEMBLY
// ============================================================
color("SteelBlue",0.5) ring_v2();
color("Gold")          sun_v2();
color("Tomato")        planets_v2();
color("LimeGreen",0.6) carrier_v2();
'}

