        translate([0,0,Zg])linear_extrude(height=gear_h,convexity=10)int_bore_2d(Nr,modul,PA,bl);
        translate([0,0,-0.01])cylinder(r=carrier_r2+rclr,h=base_h+aclr+0.01);
