    for(i=[0:Nplan-1])rotate([0,0,i*360/Nplan])translate([Rorb,0,0])cylinder(r=axle_r,h=Zt+top_h);
    translate([0,0,Zt])difference(){cylinder(r=carrier_r2,h=top_h);translate([0,0,-0.1])cylinder(r=sun_sr+rclr,h=top_h+0.2);}
