{'content': '// ============================================================
// Print-in-Place Planetary Gearbox - FINAL VERSION
// PETG | 0.4mm nozzle | 0.1mm layer height | Z-up axis
// Single stage, 3 planets, involute tooth profile
// ============================================================
$fn = 128;

// === GEAR PARAMETERS ===
modul = 1.5;
PA    = 20;
Ns    = 16;           // Sun
Np    = 8;            // Planet
Nr    = Ns + 2*Np;    // Ring = 32
Nplan = 3;

Rps  = modul*Ns/2;    // 12
Rpp  = modul*Np/2;    // 6
Rpr  = modul*Nr/2;    // 24
Rorb = Rps + Rpp;     // 18

ring_tip  = Rpr - modul;        // 23
ring_root = Rpr + 1.25*modul;   // 25.875
sun_ded   = Rps - 1.25*modul;   // 10.125

// === CLEARANCES ===
bl   = 0.50;    // Gear backlash (total)
rclr = 0.35;    // Radial clearance
aclr = 0.40;    // Axial clearance

// === DIMENSIONS ===
gear_h  = 14;     // Tooth height
base_h  = 3.0;    // Bottom carrier plate
top_h   = 3.0;    // Top carrier plate
chamfer = 1.5;    // 45° transition chamfer height

// Z coordinates
Z0  = 0;
Zbc = base_h;              // Top of base carrier plate
Zbr = Zbc + aclr;          // Bottom of bridge/chamfer zone
Zg  = Zbr + chamfer;       // Bottom of gear teeth
Zgt = Zg + gear_h;         // Top of gear teeth
Ztr = Zgt + chamfer;       // Top of bridge/chamfer zone
Ztc = Ztr + aclr;          // Bottom of top carrier plate
ZZ  = Ztc + top_h;         // Top of ring body

ring_OR  = ring_root + 3.5;     // ~29.4
axle_r   = 2.0;
sun_sr   = sun_ded - 1.0;       // 9.125 sun shaft radius
carrier_r = ring_tip + 1.5;     // 24.5 (trapped by ring tips at 23)
out_sr   = 8;                    // Output shaft radius
in_sr    = sun_sr + 3;          // Input handle radius

echo("Ring OR:", ring_OR);
echo("Ring tip:", ring_tip);
echo("Carrier r:", carrier_r);
echo("Sun shaft:", sun_sr);
echo("Total Z:", ZZ);
echo("Gear ratio:", 1+Nr/Ns);

// ============================================================
// GEAR PROFILES
// ============================================================
function inv_a(br,r) = (r<=br) ? 0 : sqrt(r*r/(br*br)-1)*180/PI;

module ext_gear_2d(teeth, mod, pa, backlash=0) {
    pr=mod*teeth/2; br=pr*cos(pa); ar=pr+mod; rr=max(pr-1.25*mod,0.5);
    ta=360/teeth; n=20;
    pii=inv_a(br,pr); ht=90/teeth-(backlash/2)/pr*180/PI; sr=max(br,rr);
    polygon([for(t=[0:teeth-1]) each [
        let(a=t*ta-ht-pii+inv_a(br,sr))[sr*cos(a),sr*sin(a)],
        for(i=[1:n]) let(r=sr+(ar-sr)*i/n, a=t*ta+ht+pii-inv_a(br,r))[r*cos(a),r*sin(a)],
        for(i=[n-1:-1:1]) let(r=sr+(ar-sr)*i/n, a=t*ta-ht-pii+inv_a(br,r))[r*cos(a),r*sin(a)]
    ]]);
}

module int_bore_2d(teeth, mod, pa, backlash=0) {
    pr=mod*teeth/2; br=pr*cos(pa); tr=pr-mod; rr=pr+1.25*mod;
    ta=360/teeth; n=20;
    pii=inv_a(br,pr); ht=90/teeth+(backlash/2)/pr*180/PI; sr=max(br,tr);
    polygon([for(t=[0:teeth-1]) each [
        for(i=[0:n]) let(r=rr-(rr-sr)*i/n, a=t*ta+ht+pii-inv_a(br,r))[r*cos(a),r*sin(a)],
        for(i=[1:n]) let(r=sr+(rr-sr)*i/n, a=t*ta-ht-pii+inv_a(br,r))[r*cos(a),r*sin(a)]
    ]]);
}

function planet_phase(idx) = -idx*360/Nplan*Ns/Np;

// ============================================================
// RING GEAR HOUSING
// ============================================================
module ring_housing() {
    difference() {
        union() {
            // Main body
            cylinder(r=ring_OR, h=ZZ);
            // Bottom grip flange with finger notches
            difference() {
                cylinder(r=ring_OR+3, h=3);
                for(i=[0:5]) rotate([0,0,i*60])
                    translate([ring_OR+3,0,-0.1])
                    cylinder(r=3.5, h=3.2, $fn=24);
            }
            // Top rim
            translate([0,0,ZZ-1])
            cylinder(r=ring_OR+1.5, h=1);
        }

        // --- Bottom carrier pocket ---
        // Cylindrical pocket for carrier base plate
        translate([0,0,-0.01])
        cylinder(r=carrier_r + rclr, h=Zbc + aclr/2);

        // 45° chamfer from carrier pocket to gear zone
        // Goes from r=carrier_r+rclr at Z=Zbc+aclr/2
        // down to r=ring_root at Z=Zg (the ring root is the widest ring bore)
        // Actually we need the chamfer to go from wide pocket to narrower gear zone
        // At gear zone, the bore shape is the ring gear profile
        // The widest point of ring gear bore is ring_root = 25.875
        // carrier_r+rclr = 24.85 which is LESS than ring_root!
        // So the gear zone is actually wider (at the roots between teeth)
        // The narrowest point of ring gear bore is ring_tip = 23
        // 
        // The carrier plate at r=24.5 is trapped because the ring gear TEETH
        // protrude inward to ring_tip=23 < 24.5. But between teeth, the bore
        // goes out to ring_root=25.875 > 24.5.
        //
        // For the bridge (horizontal layer between pocket and gear zone):
        // The pocket ceiling is at Zbr. Above that, the ring needs solid material
        // inward of ring_tip to form the chamfer/bridge.
        // But wait: carrier_r + rclr = 24.85, ring_root = 25.875
        // The pocket bore is SMALLER than the ring root bore!
        // So the transition is: pocket (r=24.85) -> gear zone (inner profile varies 23-25.875)
        //
        // The overhang issue: at the gear zone floor, the ring bore suddenly
        // has tooth-shaped features. The tooth tips at r=23 need material
        // extending inward from the pocket wall at r=24.85.
        // That's an inward overhang of 1.85mm over 0 height (bridge).
        // 
        // For 45° self-supporting: we need the chamfer height = overhang distance
        // chamfer_h = carrier_r + rclr - ring_tip = 24.85 - 23 = 1.85mm
        // So chamfer of 1.5mm is close. Let me increase to 2mm.

        // Actually, the bridge/transition zone between pocket and gear teeth:
        // Use a cone that transitions from pocket radius to ring_tip radius
        translate([0,0,Zbc + aclr/2])
        cylinder(r1=carrier_r+rclr, r2=ring_tip, h=chamfer);

        // Then gear teeth from Zg to Zgt  
        translate([0,0,Zg])
        linear_extrude(height=gear_h, convexity=10)
        int_bore_2d(Nr, modul, PA, bl);

        // Top chamfer: from gear zone to top pocket
        translate([0,0,Zgt])
        cylinder(r1=ring_tip, r2=carrier_r+rclr, h=chamfer);

        // Top carrier pocket
        translate([0,0,Ztr + aclr/2])
        cylinder(r=carrier_r+rclr, h=ZZ - (Ztr+aclr/2) + 0.01);

        // --- Sun shaft through-hole ---
        translate([0,0,-5])
        cylinder(r=sun_sr + rclr, h=ZZ+15);

        // --- Carrier output shaft hole through top ---
        translate([0,0,Ztc + top_h - 0.01])
        cylinder(r=out_sr + rclr, h=10);
    }
}

// ============================================================
// SUN GEAR (Input)
// ============================================================
module sun_gear() {
    // Gear teeth
    translate([0,0,Zg])
    linear_extrude(height=gear_h, convexity=10)
    ext_gear_2d(Ns, modul, PA, bl);

    // Shaft through ring
    cylinder(r=sun_sr, h=ZZ);

    // Input hex handle below
    translate([0,0,-14])
    linear_extrude(height=14)
    circle(r=in_sr, $fn=6);

    // Small cap on top
    translate([0,0,ZZ])
    linear_extrude(height=4)
    circle(r=sun_sr+1, $fn=6);
}

// ============================================================
// PLANET GEARS
// ============================================================
module planet_gears() {
    for(i=[0:Nplan-1]) {
        rotate([0,0,i*360/Nplan])
        translate([Rorb,0,Zg])
        rotate([0,0,planet_phase(i)])
        difference() {
            linear_extrude(height=gear_h, convexity=10)
            ext_gear_2d(Np, modul, PA, bl);
            translate([0,0,-0.1])
            cylinder(r=axle_r+rclr, h=gear_h+0.2);
        }
    }
}

// ============================================================
// CARRIER (Output)
// ============================================================
module carrier() {
    // Bottom plate
    difference() {
        cylinder(r=carrier_r, h=base_h);
        translate([0,0,-0.1])
        cylinder(r=sun_sr+rclr, h=base_h+0.2);
    }

    // Axle pins (bottom plate through gear zone to top plate)
    for(i=[0:Nplan-1])
        rotate([0,0,i*360/Nplan])
        translate([Rorb,0,0])
        cylinder(r=axle_r, h=Ztc + top_h);

    // Top plate
    translate([0,0,Ztc])
    difference() {
        cylinder(r=carrier_r, h=top_h);
        translate([0,0,-0.1])
        cylinder(r=sun_sr+rclr, h=top_h+0.2);
    }

    // Output hex shaft
    translate([0,0,Ztc + top_h])
    difference() {
        linear_extrude(height=12)
        circle(r=out_sr, $fn=6);
        translate([0,0,-0.1])
        cylinder(r=sun_sr+rclr+0.5, h=12.2);
    }
}

// ============================================================
// FINAL ASSEMBLY
// ============================================================
color("SteelBlue",0.5) ring_housing();
color("Gold")          sun_gear();
color("Tomato")        planet_gears();
color("LimeGreen",0.6) carrier();
'}

