        // Bottom pocket
        translate([0,0,-0.01])cylinder(r=carrier_r+rclr,h=Zbc+aclr/2);
        // Bottom chamfer
        translate([0,0,Zbc+aclr/2])cylinder(r1=carrier_r+rclr,r2=ring_tip,h=chamfer);
        // Gear teeth
        translate([0,0,Zg])linear_extrude(height=gear_h,convexity=10)int_bore_2d(Nr,modul,PA,bl);
        // Top chamfer
        translate([0,0,Zgt])cylinder(r1=ring_tip,r2=carrier_r+rclr,h=chamfer);
        // Top pocket
        translate([0,0,Ztr+aclr/2])cylinder(r=carrier_r+rclr,h=ZZ-(Ztr+aclr/2)+0.01);
        // Sun through
        translate([0,0,-5])cylinder(r=sun_sr+rclr,h=ZZ+15);
        // Output hole
        translate([0,0,Ztc+top_h-0.01])cylinder(r=out_sr+rclr,h=10);
    }
}
module sun_gear(){
    translate([0,0,Zg])linear_extrude(height=gear_h,convexity=10)ext_gear_2d(Ns,modul,PA,bl);
    cylinder(r=sun_sr,h=ZZ);
    translate([0,0,-14])linear_extrude(height=14)circle(r=in_sr,$fn=6);
    translate([0,0,ZZ])linear_extrude(height=4)circle(r=sun_sr+1,$fn=6);
}
module planet_gears(){
    for(i=[0:Nplan-1])rotate([0,0,i*360/Nplan])translate([Rorb,0,Zg])rotate([0,0,planet_phase(i)])
    difference(){linear_extrude(height=gear_h,convexity=10)ext_gear_2d(Np,modul,PA,bl);
    translate([0,0,-0.1])cylinder(r=axle_r+rclr,h=gear_h+0.2);}
}
module carrier(){
