    for(i=[0:Nplan-1])rotate([0,0,i*360/Nplan])translate([Rorb,0,0])cylinder(r=axle_r,h=Ztc+top_h);
    translate([0,0,Ztc])difference(){cylinder(r=carrier_r,h=top_h);translate([0,0,-0.1])cylinder(r=sun_sr+rclr,h=top_h+0.2);}
    translate([0,0,Ztc+top_h])difference(){linear_extrude(height=12)circle(r=out_sr,$fn=6);
    translate([0,0,-0.1])cylinder(r=sun_sr+rclr+0.5,h=12.2);}
}

// CROSS SECTION
difference(){
    union(){
        color("SteelBlue",0.5)ring_housing();
        color("Gold")sun_gear();
        color("Tomato")planet_gears();
        color("LimeGreen",0.6)carrier();
    }
