{'content': '// ============================================================
// Print-in-Place Planetary Gearbox - FINAL
// PETG | 0.4mm nozzle | 0.1mm layer height | Z-up axis
// Single stage, 3 planets, involute teeth
// ============================================================
$fn = 128;

// === GEAR PARAMETERS ===
modul = 1.5;
PA    = 20;
Ns    = 16;
Np    = 8;
Nr    = Ns + 2*Np;    // 32
Nplan = 3;

Rps  = modul*Ns/2;    // 12
Rpp  = modul*Np/2;    // 6
Rpr  = modul*Nr/2;    // 24
Rorb = Rps + Rpp;     // 18

ring_tip  = Rpr - modul;         // 23
ring_root = Rpr + 1.25*modul;    // 25.875
sun_ded   = Rps - 1.25*modul;    // 10.125

// === CLEARANCES (PETG, 0.4mm nozzle, 0.1mm layers) ===
bl   = 0.50;
rclr = 0.35;
aclr = 0.40;

// === DIMENSIONS ===
gear_h   = 14;
plate_h  = 3.0;     // Carrier plate thickness
chamfer  = 2.0;     // 45° chamfer height for overhang support
lip_h    = 2.0;     // Retaining lip at bottom and top

ring_OR  = ring_root + 3.5;
axle_r   = 2.0;
sun_sr   = sun_ded - 1.0;   // 9.125
carrier_r = ring_tip + 1.5; // 24.5
out_sr   = 9;
in_sr    = sun_sr + 4;

// Z-STACK (bottom to top):
// lip_h: ring lip below carrier (retains carrier at bottom)
// plate_h: carrier bottom plate
// aclr: axial gap
// chamfer: 45° transition from pocket to gear zone
// gear_h: gear teeth
// chamfer: 45° transition from gear zone to pocket
// aclr: axial gap
// plate_h: carrier top plate
// lip_h: ring lip above carrier (retains carrier at top)

Zlip_bot = 0;                        // Bottom lip start
Zbase    = lip_h;                    // Carrier base plate start
Zbc_top  = Zbase + plate_h;         // Carrier base plate top
Zgap1    = Zbc_top + aclr;          // End of bottom gap
Zcham1   = Zgap1 + chamfer;         // End of bottom chamfer = gear start
Zgear    = Zcham1;                   // Gear zone start
Zgear_top= Zgear + gear_h;          // Gear zone end
Zcham2   = Zgear_top + chamfer;     // End of top chamfer
Zgap2    = Zcham2 + aclr;           // End of top gap
Ztop     = Zgap2;                    // Carrier top plate start
Ztop_top = Ztop + plate_h;          // Carrier top plate top
ZZ       = Ztop_top + lip_h;        // Ring top = total height

echo("Total height:", ZZ);
echo("Gear zone:", Zgear, "to", Zgear_top);
echo("Gear ratio:", 1+Nr/Ns);

// ============================================================
// INVOLUTE PROFILES
// ============================================================
function inv_a(br,r) = (r<=br) ? 0 : sqrt(r*r/(br*br)-1)*180/PI;

module ext_gear_2d(teeth, mod, pa, backlash=0) {
    pr=mod*teeth/2; br=pr*cos(pa); ar=pr+mod; rr=max(pr-1.25*mod,0.5);
    ta=360/teeth; n=20;
    pii=inv_a(br,pr); ht=90/teeth-(backlash/2)/pr*180/PI; sr=max(br,rr);
    polygon([for(t=[0:teeth-1]) each [
        let(a=t*ta-ht-pii+inv_a(br,sr)) [sr*cos(a),sr*sin(a)],
        for(i=[1:n]) let(r=sr+(ar-sr)*i/n, a=t*ta+ht+pii-inv_a(br,r)) [r*cos(a),r*sin(a)],
        for(i=[n-1:-1:1]) let(r=sr+(ar-sr)*i/n, a=t*ta-ht-pii+inv_a(br,r)) [r*cos(a),r*sin(a)]
    ]]);
}

module int_bore_2d(teeth, mod, pa, backlash=0) {
    pr=mod*teeth/2; br=pr*cos(pa); tr=pr-mod; rr=pr+1.25*mod;
    ta=360/teeth; n=20;
    pii=inv_a(br,pr); ht=90/teeth+(backlash/2)/pr*180/PI; sr=max(br,tr);
    polygon([for(t=[0:teeth-1]) each [
        for(i=[0:n]) let(r=rr-(rr-sr)*i/n, a=t*ta+ht+pii-inv_a(br,r)) [r*cos(a),r*sin(a)],
        for(i=[1:n]) let(r=sr+(rr-sr)*i/n, a=t*ta-ht-pii+inv_a(br,r)) [r*cos(a),r*sin(a)]
    ]]);
}

function planet_phase(idx) = -idx*360/Nplan*Ns/Np;

// ============================================================
// RING HOUSING
// ============================================================
module ring_housing() {
    difference() {
        union() {
            // Main body
            cylinder(r=ring_OR, h=ZZ);
            // Bottom flange with grip notches
            difference() {
                cylinder(r=ring_OR+3, h=3);
                for(i=[0:5]) rotate([0,0,i*60])
                    translate([ring_OR+3,0,-0.1])
                    cylinder(r=4, h=3.2, $fn=24);
            }
            // Top flange
            translate([0,0,ZZ-1.5])
            cylinder(r=ring_OR+2, h=1.5);
        }

        // === BOTTOM LIP: ring floor has a hole just for sun shaft ===
        // The lip region (Z=0 to lip_h) is solid except for sun shaft hole
        // This is the retaining floor for the carrier
        // (sun shaft hole is cut later as through-hole)

        // === BOTTOM CARRIER POCKET ===
        // From Z=lip_h to Z=Zbc_top+aclr/2: cylindrical pocket
        translate([0,0,Zbase])
        cylinder(r=carrier_r + rclr, h=plate_h + aclr/2);

        // === BOTTOM CHAMFER (45° transition) ===
        translate([0,0,Zgap1])
        cylinder(r1=carrier_r+rclr, r2=ring_tip, h=chamfer);

        // === GEAR TEETH ===
        translate([0,0,Zgear])
        linear_extrude(height=gear_h, convexity=10)
        int_bore_2d(Nr, modul, PA, bl);

        // === TOP CHAMFER (45° transition) ===
        translate([0,0,Zgear_top])
        cylinder(r1=ring_tip, r2=carrier_r+rclr, h=chamfer);

        // === TOP CARRIER POCKET ===
        translate([0,0,Zcham2+aclr/2])
        cylinder(r=carrier_r+rclr, h=plate_h + aclr/2);

        // === TOP LIP: solid except sun shaft ===
        // (just don't cut anything here besides sun shaft)

        // === SUN SHAFT THROUGH-HOLE (full height) ===
        translate([0,0,-5])
        cylinder(r=sun_sr + rclr, h=ZZ+20);

        // === OUTPUT SHAFT HOLE through top lip ===
        translate([0,0,Ztop_top])
        cylinder(r=out_sr + rclr, h=lip_h + 5);

        // === INPUT SHAFT HOLE through bottom lip ===
        // The sun input handle needs to pass through the bottom lip
        // But wait - the sun shaft (r=sun_sr) already passes through.
        // The hex input handle is below the ring, so it's fine.
        // We just need sun_sr + rclr sized hole through the lip.
        // Already covered by the through-hole above.

        // === CARRIER AXLE CHANNELS through lips ===
        // The carrier axle pins (at Rorb, r=axle_r) pass through the lip regions.
        // In the bottom lip, we need clearance for the axle pins.
        // Since the carrier rotates, we need annular grooves.

        // Bottom lip: annular groove for axle pins
        translate([0,0,-0.01])
        difference() {
            cylinder(r=Rorb + axle_r + rclr, h=lip_h + 0.01);
            cylinder(r=Rorb - axle_r - rclr, h=lip_h + 0.02);
        }

        // Top lip: annular groove for axle pins
        translate([0,0,Ztop_top])
        difference() {
            cylinder(r=Rorb + axle_r + rclr, h=lip_h + 0.01);
            cylinder(r=Rorb - axle_r - rclr, h=lip_h + 0.02);
        }
    }
}

// ============================================================
// SUN GEAR (Input)
// ============================================================
module sun_gear() {
    // Gear teeth
    translate([0,0,Zgear])
    linear_extrude(height=gear_h, convexity=10)
    ext_gear_2d(Ns, modul, PA, bl);

    // Shaft through ring
    cylinder(r=sun_sr, h=ZZ);

    // Input hex handle below ring
    translate([0,0,-14])
    linear_extrude(height=14)
    circle(r=in_sr, $fn=6);

    // Small cap above ring
    translate([0,0,ZZ])
    linear_extrude(height=4)
    circle(r=sun_sr+1.5, $fn=6);
}

// ============================================================
// PLANET GEARS
// ============================================================
module planet_gears() {
    for(i=[0:Nplan-1]) {
        rotate([0,0,i*360/Nplan])
        translate([Rorb, 0, Zgear])
        rotate([0,0, planet_phase(i)])
        difference() {
            linear_extrude(height=gear_h, convexity=10)
            ext_gear_2d(Np, modul, PA, bl);
            translate([0,0,-0.1])
            cylinder(r=axle_r+rclr, h=gear_h+0.2);
        }
    }
}

// ============================================================
// CARRIER (Output)
// ============================================================
module carrier() {
    // Bottom plate
    translate([0,0,Zbase])
    difference() {
        cylinder(r=carrier_r, h=plate_h);
        translate([0,0,-0.1])
        cylinder(r=sun_sr+rclr, h=plate_h+0.2);
    }

    // Axle pins (from base plate through to top plate)
    for(i=[0:Nplan-1])
        rotate([0,0,i*360/Nplan])
        translate([Rorb, 0, Zbase])
        cylinder(r=axle_r, h=Ztop+plate_h-Zbase);

    // Top plate
    translate([0,0,Ztop])
    difference() {
        cylinder(r=carrier_r, h=plate_h);
        translate([0,0,-0.1])
        cylinder(r=sun_sr+rclr, h=plate_h+0.2);
    }

    // Output hex shaft above ring
    translate([0,0,Ztop_top])
    difference() {
        linear_extrude(height=12)
        circle(r=out_sr, $fn=6);
        translate([0,0,-0.1])
        cylinder(r=sun_sr+rclr+0.5, h=12.2);
    }
}

// ============================================================
// ASSEMBLY
// ============================================================
color("SteelBlue",0.5) ring_housing();
color("Gold")          sun_gear();
color("Tomato")        planet_gears();
color("LimeGreen",0.6) carrier();
'}

