{'content': '// ============================================================
// Print-in-Place Planetary Gearbox - FINAL v4
// PETG | 0.4mm nozzle | 0.1mm layer height | Z-up axis
// Single stage, 3 planets, involute teeth
//
// DESIGN: Ring retains carrier via chamfer-narrowing.
// Bottom/top lips use bridge spokes instead of full annular grooves.
// ============================================================
$fn = 128;

// === GEAR PARAMETERS ===
modul = 1.5;
PA    = 20;
Ns    = 16;
Np    = 8;
Nr    = Ns + 2*Np;    // 32
Nplan = 3;

Rps  = modul*Ns/2;    // 12
Rpp  = modul*Np/2;    // 6
Rpr  = modul*Nr/2;    // 24
Rorb = Rps + Rpp;     // 18

ring_tip  = Rpr - modul;         // 23
ring_root = Rpr + 1.25*modul;    // 25.875

// === CLEARANCES ===
bl   = 0.50;
rclr = 0.35;
aclr = 0.40;

// === DIMENSIONS ===
gear_h   = 14;
plate_h  = 3.0;
chamfer  = 2.0;
lip_h    = 2.0;

ring_OR  = ring_root + 3.5;       // ~29.4
axle_r   = 2.0;
sun_sr   = Rps - 1.25*modul - 1;  // ~9.125
carrier_r = ring_tip + 1.5;       // 24.5
out_sr   = 9;
in_sr    = sun_sr + 4;            // ~13.125

// Z coordinates
Zbase    = lip_h;
Zbc_top  = Zbase + plate_h;
Zgap1_top= Zbc_top + aclr;
Zgear    = Zgap1_top + chamfer;
Zgear_top= Zgear + gear_h;
Zcham2_top=Zgear_top + chamfer;
Zgap2_top= Zcham2_top + aclr;
Ztop     = Zgap2_top;
Ztop_top = Ztop + plate_h;
ZZ       = Ztop_top + lip_h;

echo("Total height:", ZZ);
echo("Gear zone:", Zgear, "-", Zgear_top);

// ============================================================
// INVOLUTE PROFILES
// ============================================================
function inv_a(br,r) = (r<=br) ? 0 : sqrt(r*r/(br*br)-1)*180/PI;

module ext_gear_2d(teeth, mod, pa, backlash=0) {
    pr=mod*teeth/2; br=pr*cos(pa); ar=pr+mod; rr=max(pr-1.25*mod,0.5);
    ta=360/teeth; n=20;
    pii=inv_a(br,pr); ht=90/teeth-(backlash/2)/pr*180/PI; sr=max(br,rr);
    polygon([for(t=[0:teeth-1]) each [
        let(a=t*ta-ht-pii+inv_a(br,sr)) [sr*cos(a),sr*sin(a)],
        for(i=[1:n]) let(r=sr+(ar-sr)*i/n, a=t*ta+ht+pii-inv_a(br,r)) [r*cos(a),r*sin(a)],
        for(i=[n-1:-1:1]) let(r=sr+(ar-sr)*i/n, a=t*ta-ht-pii+inv_a(br,r)) [r*cos(a),r*sin(a)]
    ]]);
}

module int_bore_2d(teeth, mod, pa, backlash=0) {
    pr=mod*teeth/2; br=pr*cos(pa); tr=pr-mod; rr=pr+1.25*mod;
    ta=360/teeth; n=20;
    pii=inv_a(br,pr); ht=90/teeth+(backlash/2)/pr*180/PI; sr=max(br,tr);
    polygon([for(t=[0:teeth-1]) each [
        for(i=[0:n]) let(r=rr-(rr-sr)*i/n, a=t*ta+ht+pii-inv_a(br,r)) [r*cos(a),r*sin(a)],
        for(i=[1:n]) let(r=sr+(rr-sr)*i/n, a=t*ta-ht-pii+inv_a(br,r)) [r*cos(a),r*sin(a)]
    ]]);
}

function planet_phase(idx) = -idx*360/Nplan*Ns/Np;

// ============================================================
// RING HOUSING
// Key insight: Instead of annular grooves in lips (which disconnect
// the ring), use individual arc-shaped slots for each axle pin position.
// Since the carrier rotates, the slots need to be full arcs.
// But full arcs = annular groove = same problem.
//
// ALTERNATIVE: Don't use lips at all. Instead, trap the carrier
// using the chamfer geometry alone. The carrier plate at r=24.5
// can't pass through the gear zone where ring_tip=23.
// So the carrier is trapped between the two chamfer transitions.
// No lips needed! The bottom of the ring is just the carrier pocket floor.
//
// But then the carrier can slide out the bottom/top if the pockets
// are open on those sides. Solution: make the pocket a closed cavity.
// The ring bottom floor and top ceiling close the pockets.
// The sun shaft hole and output shaft hole are the only openings.
//
// BOTTOM: Ring solid from Z=0 to Z=lip_h, with only sun shaft hole.
//         Carrier plate sits on this floor (with clearance gap).
//         Axle pins DON'T extend through the bottom lip.
//         Instead, axle pins only go from base plate through gear zone to top plate.
//
// TOP:    Ring solid from Z=Ztop_top to ZZ, with output shaft hole.
//         Carrier top plate is below this ceiling.
//         Axle pins DON'T extend through the top lip.
//
// This way, the lips are simple solid discs and the carrier is fully trapped!
// The axle pins connect only between the two carrier plates.
// ============================================================

module ring_housing() {
    difference() {
        union() {
            // Main body
            cylinder(r=ring_OR, h=ZZ);
            // Bottom grip flange
            difference() {
                cylinder(r=ring_OR+3, h=3);
                for(i=[0:5]) rotate([0,0,i*60])
                    translate([ring_OR+3,0,-0.1])
                    cylinder(r=4, h=3.2, $fn=24);
            }
            // Top decoration ring
            translate([0,0,ZZ-1.5])
            cylinder(r=ring_OR+2, h=1.5);
        }

        // --- Bottom carrier pocket (closed floor, open ceiling into chamfer) ---
        // Floor is at Z=lip_h (ring solid below)
        // Ceiling transitions into chamfer
        translate([0,0,Zbase - aclr])  // small gap below carrier plate
        cylinder(r=carrier_r + rclr, h=plate_h + 2*aclr);

        // --- Bottom chamfer (45° from pocket to gear zone) ---
        translate([0,0,Zbc_top + aclr])
        cylinder(r1=carrier_r+rclr, r2=ring_tip, h=chamfer);

        // --- Gear teeth zone ---
        translate([0,0,Zgear])
        linear_extrude(height=gear_h, convexity=10)
        int_bore_2d(Nr, modul, PA, bl);

        // --- Top chamfer (45° from gear zone to pocket) ---
        translate([0,0,Zgear_top])
        cylinder(r1=ring_tip, r2=carrier_r+rclr, h=chamfer);

        // --- Top carrier pocket ---
        translate([0,0,Zcham2_top - aclr])
        cylinder(r=carrier_r+rclr, h=plate_h + 2*aclr);

        // --- Sun shaft through-hole (full height) ---
        translate([0,0,-5])
        cylinder(r=sun_sr + rclr, h=ZZ+20);

        // --- Output shaft hole through top lip ---
        translate([0,0,Ztop_top])
        cylinder(r=out_sr + rclr, h=lip_h + 5);

        // --- Axle pin clearance in bottom lip ---
        // Axle pins start at Zbase (on the carrier base plate top surface)
        // But the base plate bottom is at Zbase, and below that is the lip.
        // If axle pins start at Zbase, they don't enter the lip. ✓
        // However, the carrier base plate has the axle pins attached.
        // The axle pins need to start from the base plate and go up.
        // So the bottom of the axle pins = bottom of base plate = Zbase.
        // The lip (Z=0 to Zbase) is clear of axle pins. ✓
    }
}

// ============================================================
// SUN GEAR
// ============================================================
module sun_gear() {
    // Gear teeth
    translate([0,0,Zgear])
    linear_extrude(height=gear_h, convexity=10)
    ext_gear_2d(Ns, modul, PA, bl);

    // Shaft through entire ring
    cylinder(r=sun_sr, h=ZZ);

    // Input hex handle below
    translate([0,0,-14])
    linear_extrude(height=14)
    circle(r=in_sr, $fn=6);

    // Small indicator cap above
    translate([0,0,ZZ])
    linear_extrude(height=4)
    circle(r=sun_sr+1.5, $fn=6);
}

// ============================================================
// PLANET GEARS
// ============================================================
module planet_gears() {
    for(i=[0:Nplan-1]) {
        rotate([0,0,i*360/Nplan])
        translate([Rorb, 0, Zgear])
        rotate([0,0, planet_phase(i)])
        difference() {
            linear_extrude(height=gear_h, convexity=10)
            ext_gear_2d(Np, modul, PA, bl);
            translate([0,0,-0.1])
            cylinder(r=axle_r+rclr, h=gear_h+0.2);
        }
    }
}

// ============================================================
// CARRIER (Output)
// Axle pins go from base plate up through gear zone to top plate.
// Pins do NOT extend into lip regions.
// ============================================================
module carrier() {
    // Bottom plate
    translate([0,0,Zbase])
    difference() {
        cylinder(r=carrier_r, h=plate_h);
        translate([0,0,-0.1])
        cylinder(r=sun_sr+rclr, h=plate_h+0.2);
    }

    // Axle pins: from bottom of base plate to top of top plate
    pin_z_start = Zbase;
    pin_z_end = Ztop + plate_h;
    for(i=[0:Nplan-1])
        rotate([0,0,i*360/Nplan])
        translate([Rorb, 0, pin_z_start])
        cylinder(r=axle_r, h=pin_z_end - pin_z_start);

    // Top plate
    translate([0,0,Ztop])
    difference() {
        cylinder(r=carrier_r, h=plate_h);
        translate([0,0,-0.1])
        cylinder(r=sun_sr+rclr, h=plate_h+0.2);
    }

    // Output hex shaft through top lip
    translate([0,0,Ztop_top])
    difference() {
        linear_extrude(height=lip_h + 10)
        circle(r=out_sr, $fn=6);
        translate([0,0,-0.1])
        cylinder(r=sun_sr+rclr+0.5, h=lip_h+10.2);
    }
}

// ============================================================
// ASSEMBLY
// ============================================================
color("SteelBlue",0.5) ring_housing();
color("Gold")          sun_gear();
color("Tomato")        planet_gears();
color("LimeGreen",0.6) carrier();
'}

